window.__TNPSC_REGISTER_TEST__("gk", 1, [{"id":1,"subject":"gk","testNumber":1,"question":"1921-ஆம் ஆண்டு சிந்துசமவெளி நாகரிகத்தின் முதன்மை நகரமான ஹரப்பாவில் அகழ்வாய்வைத் தொடங்கிய இந்திய தொல்லியல் அறிஞர் யார்?","options":["எஸ்.ஆர். ராவ்","சர் ஜான் மார்ஷல்","ஆர்.டி. பானர்ஜி","தயாராம் சஹானி"],"correctAnswer":3,"explanation":"1921-ஆம் ஆண்டு பஞ்சாப் பகுதியில் ராவி நதிக்கரையில் அமைந்துள்ள ஹரப்பா நகரத்தை தயாராம் சஹானி அகழ்வாய்வு செய்தார். இதுவே முதன்முதலில் கண்டறியப்பட்ட நகரமாகையால் இந்நாகரிகம் 'ஹரப்பா நாகரிகம்' எனவும் அழைக்கப்படுகிறது. 1922-இல் ஆர்.டி. பானர்ஜி மொகஞ்சதாரோவைக் கண்டறிந்தார்.","difficulty":"easy","topic":"சிந்துசமவெளி நாகரிகம்"},{"id":2,"subject":"gk","testNumber":1,"question":"மொகஞ்சதாரோவில் கண்டெடுக்கப்பட்ட பெருங்குளத்தின் (Great Bath) சுவர்கள் நீர் கசியாமல் இருக்க எதனால் பூசப்பட்டிருந்தன?","options":["செம்மண் பூச்சு","சுண்ணாம்புக் காரை","களிமண் கலவை","இயற்கை தார் (பிட்டுமன்)"],"correctAnswer":3,"explanation":"மொகஞ்சதாரோவில் உள்ள பெருங்குளம் சுட்ட செங்கற்களால் கட்டப்பட்ட செவ்வக வடிவ நீர்நிலையாகும். இதன் தளம் மற்றும் சுவர்களில் நீர் கசியாமல் தடுக்க இயற்கை தார் (Bitumen) கொண்டு பூசப்பட்டிருந்தது. இதன் வடக்கு மற்றும் தெற்குப் பகுதிகளில் படிக்கட்டுகளும், பக்கவாட்டில் உடை மாற்றும் அறைகளும் அமைந்திருந்தன.","difficulty":"easy","topic":"சிந்துசமவெளி நாகரிகம்"},{"id":3,"subject":"gk","testNumber":1,"question":"சிந்துசமவெளி நாகரிகத்தில் கப்பல் கட்டும் மற்றும் செப்பனிடும் தளம் (Dockyard) கண்டெடுக்கப்பட்ட துறைமுக நகரம் எது?","options":["லோத்தல்","சான்ஹுதாரோ","பனாவாலி","காலிபங்கன்"],"correctAnswer":0,"explanation":"குஜராத் மாநிலத்தில் சபர்மதி ஆற்றின் துணை ஆறான போகவோ நதிக்கரையில் அமைந்துள்ள லோத்தலில் உலகின் மிகப் பழமையான கப்பல் கட்டும் தளம் கண்டெடுக்கப்பட்டது. இது சிந்துசமவெளி மக்கள் மெசபடோமியா உள்ளிட்ட நாடுகளுடன் கடல்வழி வாணிபம் செய்ததற்கான வலுவான சான்றாகும்.","difficulty":"easy","topic":"சிந்துசமவெளி நாகரிகம்"},{"id":4,"subject":"gk","testNumber":1,"question":"சிந்துசமவெளி நாகரிகத்தின் எந்தத் தொல்லியல் தளத்தில் உழுத வயலின் தடயங்கள் (Ploughed Field) மற்றும் வேள்விப் பீடங்கள் கண்டெடுக்கப்பட்டன?","options":["ரக்கிகார்கி","தோலவிரா","ரூபார்","காலிபங்கன்"],"correctAnswer":3,"explanation":"ராஜஸ்தான் மாநிலத்தில் காகர் நதிக்கரையில் அமைந்துள்ள காலிபங்கனில் உழுத நிலத்தின் சான்றுகளும், இரட்டைப் பயிர் சாகுபடி முறையும் கண்டறியப்பட்டுள்ளன. மேலும் இங்கு தீ வளர்க்கும் வேள்விப் பீடங்களும் (Fire Altars) கறுப்பு வளையல்களும் கிடைத்துள்ளன.","difficulty":"medium","topic":"சிந்துசமவெளி நாகரிகம்"},{"id":5,"subject":"gk","testNumber":1,"question":"மொகஞ்சதாரோவில் கண்டெடுக்கப்பட்ட புகழ்பெற்ற 'நடனமாடும் பெண்' (Dancing Girl) சிலை எந்த உலோகத்தால் உருவாக்கப்பட்டது?","options":["தாமிரம்","வெண்கலம்","இரும்பு","வெள்ளி"],"correctAnswer":1,"explanation":"மொகஞ்சதாரோவில் கண்டெடுக்கப்பட்ட 'நடனமாடும் பெண்' சிலை வெண்கலத்தால் 'மெழுகு அச்சு முறை' (Lost-wax technique) மூலம் உருவாக்கப்பட்டது. இதனைக் கண்ட சர் ஜான் மார்ஷல், இது வரலாற்றுக்கு முந்தைய காலத்திய கலைப் படைப்பு என்று நம்ப முடியாத அளவிற்குத் தத்ரூபமாக உள்ளது எனப் பாராட்டினார்.","difficulty":"easy","topic":"சிந்துசமவெளி நாகரிகம்"},{"id":6,"subject":"gk","testNumber":1,"question":"1861-ஆம் ஆண்டு இந்திய தொல்லியல் துறையை (ASI) நிறுவி அதன் முதல் இயக்குநராகப் பணியாற்றியவர் யார்?","options":["சார்லஸ் மேசன்","சர் மார்ட்டிமர் வீலர்","அலெக்சாண்டர் கன்னிங்காம்","சர் ஜான் மார்ஷல்"],"correctAnswer":2,"explanation":"நில அளவையாளரான அலெக்சாண்டர் கன்னிங்காமின் உதவியுடன் 1861-ஆம் ஆண்டு இந்திய தொல்லியல் துறை (Archaeological Survey of India) நிறுவப்பட்டது. இதன் தலைமையகம் புதுதில்லியில் உள்ளது. அலெக்சாண்டர் கன்னிங்காம் 'இந்திய தொல்லியலின் தந்தை' எனப் போற்றப்படுகிறார்.","difficulty":"hard","topic":"சிந்துசமவெளி நாகரிகம்"},{"id":7,"subject":"gk","testNumber":1,"question":"குஜராத்தின் கட்ச் மாவட்டத்தில் அமைந்துள்ள, மூன்று அடுக்கு நகரமைப்பு மற்றும் மேம்பட்ட நீர் மேலாண்மை அமைப்புக்குப் புகழ்பெற்ற சிந்துசமவெளி நகரம் எது?","options":["அம்ரி","கோட் திஜி","தோலவிரா","சுர்கோடடா"],"correctAnswer":2,"explanation":"மற்ற ஹரப்பா நகரங்கள் மேற்குக் கோட்டை மற்றும் கீழ்நகரம் என இரு பிரிவுகளாக இருந்த நிலையில், தோலவிரா மட்டும் கோட்டை, நடுநகரம், கீழ்நகரம் என மூன்று அடுக்குகளைக் கொண்டிருந்தது. இங்கு மழைநீரைச் சேமிக்கும் பிரம்மாண்ட கற்களால் கட்டப்பட்ட நீர்த்தேக்கங்களும், பெரிய அறிவிப்புப் பலகையும் கண்டறியப்பட்டுள்ளன.","difficulty":"medium","topic":"சிந்துசமவெளி நாகரிகம்"},{"id":8,"subject":"gk","testNumber":1,"question":"சிந்துசமவெளி நாகரிக மக்கள் முற்றிலும் அறிந்திராத உலோகம் மற்றும் விலங்கு முறையே எவை?","options":["இரும்பு மற்றும் குதிரை","வெண்கலம் மற்றும் ஆடு","தங்கம் மற்றும் யானை","செம்பு மற்றும் காளை"],"correctAnswer":0,"explanation":"சிந்துசமவெளி நாகரிகம் ஒரு வெண்கலக் கால நாகரிகமாகும்; அங்கு வாழ்ந்த மக்களுக்கு இரும்பின் பயன்பாடு தெரியாது. மேலும் காளை, எருமை, ஆடு, யானை போன்ற விலங்குகளை அறிந்திருந்த அவர்கள் குதிரையைப் பற்றி அறிந்திருக்கவில்லை.","difficulty":"easy","topic":"சிந்துசமவெளி நாகரிகம்"},{"id":9,"subject":"gk","testNumber":1,"question":"ஹரப்பா மக்கள் ஆபரணங்கள் செய்வதற்குப் பயன்படுத்திய சிவப்பு நிற மணிக்கற்கள் எவ்வாறு அழைக்கப்படுகின்றன?","options":["ஸ்டீடைட்","லேபிஸ் லாசுலி","ஜேஸ்பர்","கார்னீலியன்"],"correctAnswer":3,"explanation":"சிந்துசமவெளி மக்கள் ஆபரணங்கள் செய்ய 'கார்னீலியன்' (Carnelian) என்ற சிவப்பு நிற மணிக்கற்களைப் பயன்படுத்தினர். மேலும் தங்கம், வெள்ளி, தந்தம், சங்கு, செம்பு மற்றும் சுடுமண் ஆகியவற்றாலும் அணிகலன்களைச் செய்து ஆண்களும் பெண்களும் அணிந்திருந்தனர்.","difficulty":"hard","topic":"சிந்துசமவெளி நாகரிகம்"},{"id":10,"subject":"gk","testNumber":1,"question":"சிந்துசமவெளி மக்களின் எழுத்து முறை குறித்த சரியான கூற்று எது?","options":["மேலிருந்து கீழாக மட்டுமே எழுதப்பட்ட சுமேரிய ஆப்பெழுத்து முறை","வலமிருந்து இடமாக மட்டுமே எழுதப்பட்ட கரோஷ்டி எழுத்து முறை","இடமிருந்து வலமாக மட்டுமே எழுதப்பட்ட பிராமி எழுத்து முறை","முதல் வரி வலமிருந்து இடமாகவும், இரண்டாவது வரி இடமிருந்து வலமாகவும் எழுதும் 'பௌஸ்ட்ரோபெடான்' முறை"],"correctAnswer":3,"explanation":"சிந்துசமவெளி எழுத்துகள் சித்திர எழுத்து வடிவம் கொண்டவை மற்றும் இதுவரை முழுமையாகப் படித்துப் பொருள் கண்டறியப்படவில்லை. இவை முதல் வரி வலமிருந்து இடமாகவும், அடுத்த வரி இடமிருந்து வலமாகவும் மாறி மாறி எழுதப்படும் 'பௌஸ்ட்ரோபெடான்' (Boustrophedon) முறையில் அமைந்துள்ளன.","difficulty":"hard","topic":"சிந்துசமவெளி நாகரிகம்"},{"id":11,"subject":"gk","testNumber":1,"question":"நான்கு வேதங்களில் மிகவும் பழமையானதும், 10 மண்டலங்கள் மற்றும் 1,028 பாடல்களைக் கொண்டதுமான வேதம் எது?","options":["சாம வேதம்","யஜுர் வேதம்","ரிக் வேதம்","அதர்வண வேதம்"],"correctAnswer":2,"explanation":"ரிக் வேதம் நான்கு வேதங்களில் மிகப் பழமையானதாகும். இதில் 10 மண்டலங்களில் 1,028 துதிப் பாடல்கள் உள்ளன. புகழ்பெற்ற காயத்ரி மந்திரம் ரிக் வேதத்தின் மூன்றாவது மண்டலத்தில் இடம்பெற்றுள்ளது.","difficulty":"easy","topic":"வேதகாலம்"},{"id":12,"subject":"gk","testNumber":1,"question":"வேள்விகளின்போது இசைக்கப்படும் பாடல்களைக் கொண்டதும், இந்திய இசையின் மூலமாகக் கருதப்படுவதுமான வேதம் எது?","options":["யஜுர் வேதம்","சாம வேதம்","அதர்வண வேதம்","ரிக் வேதம்"],"correctAnswer":1,"explanation":"சாம வேதம் இசை வடிவில் பாடப்படும் வேத மந்திரங்களைக் கொண்டுள்ளது. இது இந்திய இசை மரபின் தோற்றுவாயாகக் கருதப்படுகிறது. யஜுர் வேதம் வேள்விச் சடங்குகளையும், அதர்வண வேதம் மருத்துவம் மற்றும் மந்திரங்களையும் விளக்குகிறது.","difficulty":"easy","topic":"வேதகாலம்"},{"id":13,"subject":"gk","testNumber":1,"question":"ரிக் வேத காலத்தில் அரசனுக்கு ஆலோசனை வழங்கிய 'சபா' மற்றும் 'சமிதி' ஆகிய அமைப்புகள் முறையே எவற்றைக் குறிக்கின்றன?","options":["சபா - படைத்தளபதிகள் அவை; சமிதி - வணிகர்கள் அவை","சபா - கிராமத் தலைவர்கள் அவை; சமிதி - புரோகிதர்கள் அவை","சபா - மூத்தோர்களைக் கொண்ட அவை; சமிதி - மக்கள் அனைவரையும் கொண்ட பொது அவை","சபா - பெண்கள் மட்டும் கூடும் அவை; சமிதி - நீதிபதிகள் அவை"],"correctAnswer":2,"explanation":"ரிக் வேத கால அரசியல் அமைப்பில் 'சபா' என்பது குலத்தின் மூத்தோர்களைக் கொண்ட சிறிய அவையாகவும், 'சமிதி' என்பது மக்கள் அனைவரும் பங்கேற்கும் பொது அவையாகவும் செயல்பட்டன. இவை அரசனின் அதிகாரத்தைக் கட்டுப்படுத்தும் அமைப்புகளாகத் திகழ்ந்தன.","difficulty":"medium","topic":"வேதகாலம்"},{"id":14,"subject":"gk","testNumber":1,"question":"'சத்யமேவ ஜயதே' (வாய்மையே வெல்லும்) என்ற இந்திய தேசியக் குறிக்கோள் எந்த உபநிடதத்திலிருந்து எடுக்கப்பட்டது?","options":["பிருகதாரண்யக உபநிடதம்","சாந்தோக்ய உபநிடதம்","கடோபநிடதம்","முண்டக உபநிடதம்"],"correctAnswer":3,"explanation":"இந்திய அரசின் தேசியச் சின்னத்தின் கீழ் பொறிக்கப்பட்டுள்ள 'சத்யமேவ ஜயதே' (வாய்மையே வெல்லும்) என்ற வாசகம் 'முண்டக உபநிடதத்திலிருந்து' எடுக்கப்பட்டது. உபநிடதங்கள் என்பவை வேதங்களின் தத்துவப் பகுதியாகும்; இவை 'வேதாந்தம்' எனவும் அழைக்கப்படுகின்றன.","difficulty":"medium","topic":"வேதகாலம்"},{"id":15,"subject":"gk","testNumber":1,"question":"ரிக் வேத காலத்தில் மக்கள் அரசனுக்குத் தாமாக முன்வந்து அளித்த காணிக்கை, பின்வேத காலத்தில் கட்டாய வரியாக மாறியது; அந்த வரியின் பெயர் என்ன?","options":["பாலி","கரா","பாகா","சுல்கா"],"correctAnswer":0,"explanation":"ரிக் வேத காலத்தில் மக்கள் அரசனுக்கு விருப்பத்துடன் வழங்கிய காணிக்கை 'பாலி' (Bali) எனப்பட்டது. பின்வேத காலத்தில் அரசுகள் விரிவடைந்தபோது, இந்தப் பாலி என்பது மக்கள் தமது விளைச்சல் அல்லது கால்நடைகளில் ஆறில் ஒரு பங்கைச் செலுத்தும் கட்டாய வரியாக மாறியது.","difficulty":"hard","topic":"வேதகாலம்"},{"id":16,"subject":"gk","testNumber":1,"question":"சமண சமயத்தின் முதல் தீர்த்தங்கரர் மற்றும் 24-வது (இறுதி) தீர்த்தங்கரர் முறையே யார்?","options":["அஜிதநாதர் மற்றும் பார்சுவநாதர்","பார்சுவநாதர் மற்றும் வர்த்தமான மகாவீரர்","ரிஷபர் மற்றும் வர்த்தமான மகாவீரர்","நேமிநாதர் மற்றும் ரிஷபர்"],"correctAnswer":2,"explanation":"சமண சமய மரபில் மொத்தம் 24 தீர்த்தங்கரர்கள் உள்ளனர். அவர்களில் முதலாமவர் ரிஷபர் (ஆதிநாதர்), 23-வது தீர்த்தங்கரர் பார்சுவநாதர், மற்றும் 24-வது இறுதித் தீர்த்தங்கரர் வர்த்தமான மகாவீரர் ஆவார்.","difficulty":"easy","topic":"புத்த & சமண சமயம்"},{"id":17,"subject":"gk","testNumber":1,"question":"சமண சமயம் போதிக்கும் 'மும்மணிகள்' (திரிரத்னா) என்பவை யாவை?","options":["நன்னம்பிக்கை, நல்லறிவு, நன்னடத்தை","புத்தர், தம்மம், சங்கம்","நற்செயல், நல்வாழ்வு, நல்தியானம்","அகிம்சை, வாய்மை, துறவு"],"correctAnswer":0,"explanation":"பிறவிச் சுழற்சியிலிருந்து விடுதலை (மோட்சம்) பெறுவதற்காக மகாவீரர் போதித்த மூன்று கோட்பாடுகள் 'மும்மணிகள்' அல்லது 'திரிரத்னா' எனப்படும். அவை நன்னம்பிக்கை (Right Faith), நல்லறிவு (Right Knowledge) மற்றும் நன்னடத்தை (Right Conduct) என்பனவாகும்.","difficulty":"easy","topic":"புத்த & சமண சமயம்"},{"id":18,"subject":"gk","testNumber":1,"question":"கௌதம புத்தர் ஞானம் பெற்ற பின்னர் தனது முதல் போதனையை (தர்ம சக்ர பிரவர்த்தனா) எங்கு நிகழ்த்தினார்?","options":["குசிநகர்","புத்தகயா","லும்பினி","சாரநாத்"],"correctAnswer":3,"explanation":"கௌதம புத்தர் பீகாரில் உள்ள புத்தகயாவில் அரச மரத்தடியில் ஞானம் பெற்றார். அதன்பின் வாரணாசிக்கு அருகிலுள்ள சாரநாத் மான் பூங்காவில் தனது ஐந்து சீடர்களுக்கு முதல் போதனையை வழங்கினார்; இந்நிகழ்வு 'தர்ம சக்ர பிரவர்த்தனா' என அழைக்கப்படுகிறது.","difficulty":"easy","topic":"புத்த & சமண சமயம்"},{"id":19,"subject":"gk","testNumber":1,"question":"புத்த சமயத்தின் புனித நூல்களான 'திரிபீடகங்கள்' (விநய, சுத்த, அபிதம்ம பீடகங்கள்) எந்த மொழியில் இயற்றப்பட்டன?","options":["சௌரசேனி","பாலி","சமஸ்கிருதம்","அர்த்தமாகதி"],"correctAnswer":1,"explanation":"புத்தரின் போதனைகள் மற்றும் துறவற விதிகளைத் தொகுத்துக் கூறும் 'திரிபீடகங்கள்' (மூன்று கூடைகள்) சாமானிய மக்கள் பேசும் 'பாலி' மொழியில் இயற்றப்பட்டன. சமண சமயத்தின் 'அங்கங்கள்' பிராகிருத (அர்த்தமாகதி) மொழியில் எழுதப்பட்டன.","difficulty":"medium","topic":"புத்த & சமண சமயம்"},{"id":20,"subject":"gk","testNumber":1,"question":"வரலாற்றில் நடைபெற்ற நான்கு புத்த சமய மாநாடுகளின் இடங்களைச் சரியான காலவரிசையில் தேர்ந்தெடுக்கவும்:","options":["வைசாலி – ராஜகிருகம் – பாடலிபுத்திரம் – காஷ்மீர்","ராஜகிருகம் – பாடலிபுத்திரம் – வைசாலி – காஷ்மீர்","ராஜகிருகம் – வைசாலி – பாடலிபுத்திரம் – காஷ்மீர்","பாடலிபுத்திரம் – ராஜகிருகம் – வைசாலி – காஷ்மீர்"],"correctAnswer":2,"explanation":"முதல் புத்த மாநாடு ராஜகிருகத்திலும் (அஜாதசத்ரு), இரண்டாவது மாநாடு வைசாலியிலும் (காலசோகர்), மூன்றாவது மாநாடு பாடலிபுத்திரத்திலும் (அசோகர்), நான்காவது மாநாடு காஷ்மீரில் உள்ள குந்தலவனத்திலும் (கனிஷ்கர்) நடைபெற்றன.","difficulty":"hard","topic":"புத்த & சமண சமயம்"},{"id":21,"subject":"gk","testNumber":1,"question":"வைசாலியில் நடைபெற்ற இரண்டாவது புத்த சமய மாநாட்டிற்கு ஆதரவு அளித்த சிசுநாக வம்ச மன்னர் யார்?","options":["காலசோகர்","அஜாதசத்ரு","பிம்பிசாரர்","மகாபத்ம நந்தர்"],"correctAnswer":0,"explanation":"கி.மு. 383-ஆம் ஆண்டு வைசாலியில் நடைபெற்ற இரண்டாவது புத்த மாநாடு சிசுநாக வம்ச அரசரான காலசோகரின் ஆதரவில் சபாகமி தலைமையில் நடந்தது. இம்மாநாட்டில் புத்த சமயம் ஸ்தவிரவாதிகள் மற்றும் மகாசங்கிகர்கள் எனப் பிரிந்தது.","difficulty":"hard","topic":"புத்த & சமண சமயம்"},{"id":22,"subject":"gk","testNumber":1,"question":"கி.மு. 6-ஆம் நூற்றாண்டில் தோன்றிய பதினாறு மகாஜனபதங்களில் தென்னிந்தியாவில் கோதாவரி நதிக்கரையில் அமைந்திருந்த ஒரே மகாஜனபதம் எது?","options":["அஸ்மகம்","மல்லம்","வஜ்ஜி","அவந்தி"],"correctAnswer":0,"explanation":"கி.மு. 6-ஆம் நூற்றாண்டில் வட இந்தியாவில் 15 மகாஜனபதங்கள் அமைந்திருக்க, தென்னிந்தியாவில் கோதாவரி ஆற்றின் கரையில் அமைந்திருந்த ஒரே மகாஜனபதம் 'அஸ்மகம்' (அஸ்ஸகம்) ஆகும். இதன் தலைநகரம் போதலி (போதனா) ஆகும்.","difficulty":"hard","topic":"மகாஜனபதங்கள்"},{"id":23,"subject":"gk","testNumber":1,"question":"மகதப் பேரரசை ஆட்சி செய்த அரியங்க வம்சத்தைத் தோற்றுவித்தவரும், கௌதம புத்தரின் சமகாலத்தவருமான மன்னர் யார்?","options":["பிம்பிசாரர்","பிரத்யோதர்","தனநந்தர்","சிசுநாகர்"],"correctAnswer":0,"explanation":"மகதத்தின் எழுச்சிக்கு அடித்தளமிட்ட அரியங்க வம்சத்தைத் தோற்றுவித்தவர் பிம்பிசாரர் ஆவார். இவர் திருமண உறவுகள் மற்றும் படையெடுப்புகள் மூலம் மகதத்தை விரிவுபடுத்தினார்; இவரது மகன் அஜாதசத்ரு ஆவார்.","difficulty":"medium","topic":"மகாஜனபதங்கள்"},{"id":24,"subject":"gk","testNumber":1,"question":"'சர்வக்ஷத்ராந்தகர்' (சத்ரியர்களை அழிப்பவர்) மற்றும் 'ஏக்ரத்' எனப் புகழப்பட்ட நந்த வம்சத்தின் நிறுவனர் யார்?","options":["மகாபத்ம நந்தர்","தனநந்தர்","உதயன்","அஜாதசத்ரு"],"correctAnswer":0,"explanation":"சிசுநாக வம்சத்தை வீழ்த்தி நந்த வம்சத்தைத் தோற்றுவித்தவர் மகாபத்ம நந்தர் ஆவார். பல சத்ரிய அரசுகளை வென்று வட இந்தியாவின் முதல் பெரும் பேரரசை உருவாக்கியதால் இவர் 'சர்வக்ஷத்ராந்தகர்' மற்றும் 'ஏக்ரத்' (ஒரே பேரரசர்) என அழைக்கப்பட்டார்.","difficulty":"medium","topic":"மகாஜனபதங்கள்"},{"id":25,"subject":"gk","testNumber":1,"question":"மாசிடோனிய மன்னர் அலெக்சாண்டர் கி.மு. 326-இல் எந்தப் போரில் பஞ்சாப் மன்னர் போரஸை (புருஷோத்தமன்) தோற்கடித்தார்?","options":["பாக்சர் போர்","தரெய்ன் போர்","தசராக்ஞ போர்","ஹைடாஸ்பஸ் (ஜீலம்) போர்"],"correctAnswer":3,"explanation":"கி.மு. 326-ஆம் ஆண்டு ஜீலம் (கிரேக்கப் பெயர்: ஹைடாஸ்பஸ்) நதிக்கரையில் அலெக்சாண்டருக்கும் மன்னர் போரஸுக்கும் இடையே கடும் போர் நடைபெற்றது. போரஸின் வீரத்தைப் பாராட்டிய அலெக்சாண்டர், அவரது அரசை அவரிடமே திருப்பிக் கொடுத்து நட்புக் கொண்டார்.","difficulty":"medium","topic":"மகாஜனபதங்கள்"},{"id":26,"subject":"gk","testNumber":1,"question":"சமண சமயம் 'சுவேதாம்பரர்' (வெள்ளாடை அணிபவர்) மற்றும் 'திகம்பரர்' (ஆடை அணியாதவர்) என இரு பிரிவுகளாகப் பிரிந்ததற்குத் தலைமை தாங்கிய துறவிகள் முறையே யார்?","options":["மகாவீரர் மற்றும் கோசாலர்","ஸ்தூலபத்ரர் மற்றும் பத்ரபாகு","பார்சுவநாதர் மற்றும் மகாவீரர்","பத்ரபாகு மற்றும் ஸ்தூலபத்ரர்"],"correctAnswer":1,"explanation":"மகதத்தில் ஏற்பட்ட கடும் பஞ்சத்தின்போது பத்ரபாகு தலைமையில் தென்னிந்தியா (சரவணபெலகோலா) சென்றவர்கள் மகாவீரரின் கடுமையான விதிகளைப் பின்பற்றி 'திகம்பரர்கள்' எனப்பட்டனர். மகதத்திலேயே தங்கிய ஸ்தூலபத்ரரின் சீடர்கள் வெள்ளை ஆடை அணிந்து 'சுவேதாம்பரர்கள்' எனப்பட்டனர்.","difficulty":"hard","topic":"புத்த & சமண சமயம்"},{"id":27,"subject":"gk","testNumber":1,"question":"மகதப் பேரரசின் தலைநகரை ராஜகிருகத்திலிருந்து கங்கை மற்றும் சோன் ஆறுகள் சங்கமிக்கும் பாடலிபுத்திரத்திற்கு மாற்றிய அரியங்க வம்ச அரசர் யார்?","options":["அஜாதசத்ரு","பிம்பிசாரர்","காலசோகர்","உதயன்"],"correctAnswer":3,"explanation":"அஜாதசத்ருவின் மகனான உதயன் (உதயின்) கங்கை மற்றும் சோன் ஆறுகள் இணையும் இடத்தில் பாடலிபுத்திர நகரை உருவாக்கி, மகதத்தின் தலைநகரை ராஜகிருகத்திலிருந்து அங்கு மாற்றினார். பாடலிபுத்திரம் பின்னர் மௌரியர் மற்றும் குப்தர்களின் தலைநகரமாகவும் திகழ்ந்தது.","difficulty":"medium","topic":"மகாஜனபதங்கள்"},{"id":28,"subject":"gk","testNumber":1,"question":"சாணக்கியரின் உதவியுடன் நந்த வம்சத்தின் கடைசி அரசரான தனநந்தரைத் தோற்கடித்து மௌரியப் பேரரசை நிறுவியவர் யார்?","options":["பிருகத்ரதர்","பிந்துசாரர்","அசோகர்","சந்திரகுப்த மௌரியர்"],"correctAnswer":3,"explanation":"கி.மு. 322-இல் சந்திரகுப்த மௌரியர், சாணக்கியரின் (கௌடில்யர்) வழிகாட்டுதலுடன் தனநந்தரைத் தோற்கடித்து பாடலிபுத்திரத்தைத் தலைநகராகக் கொண்டு மௌரியப் பேரரசை நிறுவினார். விசாகதத்தர் எழுதிய 'முத்ரா ராக்ஷசம்' என்ற நாடகம் இதனை விவரிக்கிறது.","difficulty":"easy","topic":"மௌரியப் பேரரசு"},{"id":29,"subject":"gk","testNumber":1,"question":"சந்திரகுப்த மௌரியரின் தலைமை அமைச்சரான கௌடில்யர் எழுதிய 'அர்த்தசாஸ்திரம்' எந்தத் துறையைப் பற்றிய மிகச்சிறந்த நூலாகும்?","options":["ஆயுர்வேத மருத்துவம்","அரசியல், ஆட்சிமுறை மற்றும் பொருளாதாரம்","வானியல் மற்றும் கணிதம்","நாட்டியம் மற்றும் இசை"],"correctAnswer":1,"explanation":"கௌடில்யர் (சாணக்கியர் / விஷ்ணுகுப்தர்) சமஸ்கிருதத்தில் எழுதிய 'அர்த்தசாஸ்திரம்' 15 தொகுதிகளைக் கொண்ட அரசியல், அரசு நிர்வாகம், ஒற்றாடல் மற்றும் பொருளாதாரம் சார்ந்த நூலாகும். இது மௌரியர் கால ஆட்சிமுறையை அறிய உதவும் முதன்மைச் சான்றாகும்.","difficulty":"easy","topic":"மௌரியப் பேரரசு"},{"id":30,"subject":"gk","testNumber":1,"question":"செலியூகஸ் நிகேடரின் தூதுவராக சந்திரகுப்த மௌரியரின் அவைக்கு வந்து 'இண்டிகா' என்ற நூலை எழுதிய கிரேக்க அறிஞர் யார்?","options":["பிளினி","மெகஸ்தனிஸ்","டெய்மாகஸ்","டாலமி"],"correctAnswer":1,"explanation":"கிரேக்கத் தளபதி செலியூகஸ் நிகேடர் தனது தூதுவராக மெகஸ்தனிஸை சந்திரகுப்த மௌரியரின் அரசவைக்கு அனுப்பினார். மெகஸ்தனிஸ் பாடலிபுத்திரத்தில் தங்கித் தனது அனுபவங்களை 'இண்டிகா' என்ற நூலில் பதிவு செய்தார்; இந்நூல் மௌரிய நகர நிர்வாகம் மற்றும் சமூகத்தைப் பற்றிக் கூறுகிறது.","difficulty":"easy","topic":"மௌரியப் பேரரசு"},{"id":31,"subject":"gk","testNumber":1,"question":"கி.மு. 261-இல் நடைபெற்ற கலிங்கப் போரின் பேரழிவையும், அதனால் பேரரசர் அசோகருக்கு ஏற்பட்ட மனமாற்றத்தையும் விவரிக்கும் பாறைக் கல்வெட்டு எது?","options":["13-ஆம் பாறைக் கல்வெட்டு","2-ஆம் பாறைக் கல்வெட்டு","1-ஆம் பாறைக் கல்வெட்டு","7-ஆம் பாறைக் கல்வெட்டு"],"correctAnswer":0,"explanation":"அசோகரின் 13-ஆம் பெரும் பாறைக் கல்வெட்டு கலிங்கப் போரில் ஏற்பட்ட உயிரிழப்புகளையும், போர் வெற்றியை (பேரிகோஷம்) விட தர்ம வெற்றியே (தம்மகோஷம்) சிறந்தது என அசோகர் மனம் மாறியதையும் விரிவாகக் குறிப்பிடுகிறது. மேலும் இதில் தமிழக மூவேந்தர்கள் பற்றியும் குறிப்பு உள்ளது.","difficulty":"medium","topic":"மௌரியப் பேரரசு"},{"id":32,"subject":"gk","testNumber":1,"question":"அசோகரின் பிராமி எழுத்து கல்வெட்டுகளை 1837-ஆம் ஆண்டு முதன்முதலில் படித்துப் பொருள் கண்டறிந்த ஆங்கிலேய அறிஞர் யார்?","options":["வில்லியம் ஜோன்ஸ்","வின்சென்ட் ஸ்மித்","ஜேம்ஸ் பிரின்செப்","மேக்ஸ் முல்லர்"],"correctAnswer":2,"explanation":"1837-ஆம் ஆண்டு ஆங்கிலேய அறிஞர் ஜேம்ஸ் பிரின்செப், பிராமி எழுத்துகளில் பொறிக்கப்பட்டிருந்த அசோகரின் கல்வெட்டுகளை முதன்முதலில் படித்துப் பொருள் கண்டறிந்தார். இக்கல்வெட்டுகளில் அசோகர் 'தேவனாம்பிரிய பிரியதர்சி' (தேவர்களுக்குப் பிரியமானவர்) எனக் குறிப்பிடப்பட்டுள்ளார்.","difficulty":"medium","topic":"மௌரியப் பேரரசு"},{"id":33,"subject":"gk","testNumber":1,"question":"பேரரசர் அசோகர் தம்மத்தைப் (தர்மம்) பரப்புவதற்காகவும் மக்களின் நலனைக் கண்காணிப்பதற்காகவும் புதிதாக நியமித்த சிறப்பு அதிகாரிகள் யார்?","options":["தம்ம மஹாமாத்திரர்கள்","யுக்தர்கள்","பிரதேசிகள்","சமஹர்த்தா"],"correctAnswer":0,"explanation":"அசோகர் தனது ஆட்சியின் 14-வது ஆண்டில் 'தம்ம மஹாமாத்திரர்கள்' என்ற சிறப்பு அதிகாரிகளை நியமித்தார். மக்கள் நல்வழியில் நடப்பதை உறுதி செய்தல், சமயப் பொறையை வளர்த்தல் மற்றும் அனைத்துப் பிரிவினரின் நலனைக் காத்தல் இவர்களின் முக்கியப் பணிகளாகும்.","difficulty":"medium","topic":"மௌரியப் பேரரசு"},{"id":34,"subject":"gk","testNumber":1,"question":"மௌரியப் பேரரசின் கடைசி அரசரான பிருகத்ரதரைக் கொன்று கி.மு. 185-இல் சுங்க வம்சத்தை நிறுவிய படைத்தளபதி யார்?","options":["அக்னிமித்திரர்","வாசுதேவ கண்வர்","புஷ்யமித்திர சுங்கர்","சிமுகர்"],"correctAnswer":2,"explanation":"மௌரியப் பேரரசின் கடைசி மன்னரான பிருகத்ரதரை அவரது படைத்தளபதியான புஷ்யமித்திர சுங்கர் கொலை செய்து சுங்க வம்ச ஆட்சியை நிறுவினார். இவரது மகன் அக்னிமித்திரரை நாயகனாகக் கொண்டே காளிதாசர் 'மாளவிகாக்னிமித்ரம்' என்ற நாடகத்தை எழுதினார்.","difficulty":"hard","topic":"மௌரியப் பேரரசு"},{"id":35,"subject":"gk","testNumber":1,"question":"கி.பி. 78-ஆம் ஆண்டு 'சக சகாப்தத்தை' (Saka Era) தொடங்கி வைத்த குஷாணப் பேரரசர் யார்?","options":["விம காட்பிசஸ்","குஜுல காட்பிசஸ்","கனிஷ்கர்","ஹுவிஷ்கர்"],"correctAnswer":2,"explanation":"குஷாணப் பேரரசின் மிகச்சிறந்த அரசரான கனிஷ்கர் கி.பி. 78-இல் அரியணை ஏறியதைக் குறிக்கும் வகையில் 'சக சகாப்தம்' (Saka Era) தொடங்கப்பட்டது. இந்திய அரசு 1957-ஆம் ஆண்டு இதனைத் தனது தேசிய நாட்காட்டியாக ஏற்றுக்கொண்டது.","difficulty":"easy","topic":"குஷாணர்கள்"},{"id":36,"subject":"gk","testNumber":1,"question":"குஷாணப் பேரரசர் கனிஷ்கரின் அவையை அலங்கரித்த 'புத்த சரிதம்' என்ற முதல் சமஸ்கிருதக் காப்பியத்தின் ஆசிரியர் யார்?","options":["நாகார்ஜுனர்","அஸ்வகோஷர்","பதஞ்சலி","சரகர்"],"correctAnswer":1,"explanation":"கனிஷ்கரின் அரசவையில் இருந்த சிறந்த பௌத்த அறிஞரான அஸ்வகோஷர் 'புத்த சரிதம்' என்ற சமஸ்கிருத நூலை இயற்றினார். கனிஷ்கரின் அவையில் நாகார்ஜுனர், வசுமித்திரர் மற்றும் புகழ்பெற்ற மருத்துவர் சரகர் ஆகியோரும் இடம்பெற்றிருந்தனர்.","difficulty":"medium","topic":"குஷாணர்கள்"},{"id":37,"subject":"gk","testNumber":1,"question":"கனிஷ்கரின் காலத்தில் காஷ்மீரில் உள்ள குந்தலவனத்தில் நடைபெற்ற நான்காவது புத்த சமய மாநாட்டிற்குத் தலைமை தாங்கிய அறிஞர் யார்?","options":["மொக்கலிபுத்த திஸ்ஸர்","மகாகாசியபர்","சபாகமி","வசுமித்திரர்"],"correctAnswer":3,"explanation":"நான்காவது புத்த சமய மாநாடு கனிஷ்கரின் ஆதரவில் காஷ்மீர் குந்தலவனத்தில் வசுமித்திரர் தலைமையிலும், அஸ்வகோஷர் துணைத் தலைமையிலும் நடைபெற்றது. இம்மாநாட்டில் புத்த சமயம் 'ஹீனயானம்' மற்றும் 'மஹாயானம்' என இரு பெரும் பிரிவுகளாகப் பிரிந்தது.","difficulty":"hard","topic":"குஷாணர்கள்"},{"id":38,"subject":"gk","testNumber":1,"question":"தனது வட மற்றும் தென்னிந்தியப் படையெடுப்பு வெற்றிகளுக்காக வரலாற்றாசிரியர் வின்சென்ட் ஸ்மித்தால் 'இந்திய நெப்போலியன்' எனப் போற்றப்பட்ட குப்தப் பேரரசர் யார்?","options":["இரண்டாம் சந்திரகுப்தர்","முதலாம் சந்திரகுப்தர்","ஸ்ரீகுப்தர்","சமுத்திரகுப்தர்"],"correctAnswer":3,"explanation":"குப்த வம்சத்தின் சிறந்த போர் வீரரான சமுத்திரகுப்தர் வட இந்தியாவின் 9 அரசர்களையும் தென்னிந்தியாவின் 12 அரசர்களையும் வென்றார். இதனால் வரலாற்றாசிரியர் வின்சென்ட் ஸ்மித் இவரை 'இந்திய நெப்போலியன்' எனப் புகழ்ந்தார். இவர் வீணை வாசிப்பதில் வல்லவர் என்பதால் 'கவிராஜர்' எனவும் அழைக்கப்பட்டார்.","difficulty":"easy","topic":"குப்தப் பேரரசு"},{"id":39,"subject":"gk","testNumber":1,"question":"சமுத்திரகுப்தரின் படையெடுப்புகள் மற்றும் ஆட்சிச் சிறப்புகளைப் பற்றி விவரிக்கும் அலகாபாத் தூண் கல்வெட்டை (பிரயாகை மெய்க்கீர்த்தி) இயற்றிய அவைக்களப் புலவர் யார்?","options":["பாணபட்டர்","ஹரிசேனர்","விசாகதத்தர்","காளிதாசர்"],"correctAnswer":1,"explanation":"சமுத்திரகுப்தரின் அவைக்களப் புலவரும் அமைச்சருமான ஹரிசேனர், சமஸ்கிருத மொழியில் நாகரி வரிவடிவத்தில் 33 வரிகளைக் கொண்ட அலகாபாத் தூண் கல்வெட்டைப் பொறித்தார். இது சமுத்திரகுப்தரின் தட்சிணாபத மற்றும் ஆரியவர்த்தப் படையெடுப்புகளை அறிய உதவும் முதன்மைச் சான்றாகும்.","difficulty":"easy","topic":"குப்தப் பேரரசு"},{"id":40,"subject":"gk","testNumber":1,"question":"இரண்டாம் சந்திரகுப்தர் (விக்கிரமாதித்யர்) ஆட்சிக்காலத்தில் பௌத்த நூல்களைத் தேடி இந்தியாவிற்கு வருகை தந்த சீனப் பயணி யார்?","options":["பாஹியான்","இட்சிங்","சுங் யுன்","யுவான் சுவாங்"],"correctAnswer":0,"explanation":"சீன பௌத்தப் பயணியான பாஹியான் (Fa-Hien) கி.பி. 399–414 காலகட்டத்தில் இரண்டாம் சந்திரகுப்தரின் ஆட்சியில் இந்தியாவிற்கு வருகை தந்தார். மகத மக்கள் மகிழ்ச்சியாகவும் செழிப்பாகவும் வாழ்ந்ததாகவும், கடுமையான தண்டனைகள் இல்லை எனவும் இவர் தனது குறிப்புகளில் பாராட்டியுள்ளார்.","difficulty":"easy","topic":"குப்தப் பேரரசு"},{"id":41,"subject":"gk","testNumber":1,"question":"பீகாரில் உலகப் புகழ்பெற்ற நாளந்தா பல்கலைக்கழகத்தை நிறுவிய குப்தப் பேரரசர் யார்?","options":["முதலாம் குமாரகுப்தர்","ஸ்கந்தகுப்தர்","விஷ்ணுகுப்தர்","சமுத்திரகுப்தர்"],"correctAnswer":0,"explanation":"இரண்டாம் சந்திரகுப்தரின் மகனான முதலாம் குமாரகுப்தர் ('சக்ராதித்யர்' எனவும் அறியப்பட்டவர்) பீகாரில் நாளந்தா பௌத்தப் பல்கலைக்கழகத்தை நிறுவினார். இது 5-ஆம் நூற்றாண்டு முதல் 12-ஆம் நூற்றாண்டு வரை உலகின் சிறந்த கல்வி மையமாகத் திகழ்ந்தது.","difficulty":"medium","topic":"குப்தப் பேரரசு"},{"id":42,"subject":"gk","testNumber":1,"question":"பூமி தன் அச்சில் சுழல்கிறது என்பதையும், சூரிய மற்றும் சந்திர கிரகணங்களுக்கான அறிவியல் காரணத்தையும் 'ஆரியபட்டீயம்' நூலில் விளக்கிய குப்தர் கால அறிஞர் யார்?","options":["பாஸ்கரர்","வராகமிகிரர்","பிரம்மகுப்தர்","ஆரியபட்டர்"],"correctAnswer":3,"explanation":"குப்தர் காலத்தின் தலைசிறந்த வானியல் மற்றும் கணித மேதையான ஆரியபட்டர் 'ஆரியபட்டீயம்' என்ற நூலை எழுதினார். சூரிய-சந்திர கிரகணங்களுக்கான உண்மையான அறிவியல் காரணத்தை விளக்கியதோடு, பூமி தன் அச்சில் சுழல்வதால் இரவு-பகல் ஏற்படுகிறது என்பதையும் இவர் முதலில் கூறினார்.","difficulty":"easy","topic":"குப்தப் பேரரசு"},{"id":43,"subject":"gk","testNumber":1,"question":"இரண்டாம் சந்திரகுப்தரின் அவையிலிருந்த 'நவரத்தினங்களில்' ஒருவரும், 'சாகுந்தலம்', 'மேகதூதம்', 'ரகுவம்சம்' ஆகிய நூல்களின் ஆசிரியருமானவர் யார்?","options":["காளிதாசர்","அமரசிம்மர்","சூத்திரகர்","பாரவி"],"correctAnswer":0,"explanation":"'இந்தியாவின் ஷேக்ஸ்பியர்' எனப் போற்றப்படும் மகாகவி காளிதாசர் இரண்டாம் சந்திரகுப்தரின் நவரத்தினங்களில் முதன்மையானவர் ஆவார். அபிஞான சாகுந்தலம், மாளவிகாக்னிமித்ரம், விக்ரமோர்வசீயம் ஆகிய நாடகங்களையும், மேகதூதம், ரகுவம்சம், குமாரசம்பவம், ருதுசம்ஹாரம் ஆகிய காவியங்களையும் இவர் இயற்றினார்.","difficulty":"easy","topic":"குப்தப் பேரரசு"},{"id":44,"subject":"gk","testNumber":1,"question":"இரண்டாம் சந்திரகுப்தரின் அவையில் இடம்பெற்றிருந்த 'நவரத்தினங்களில்' ஒருவரும், ஆயுர்வேத மருத்துவ நிபுணருமானவர் யார்?","options":["சுஸ்ருதர்","தன்வந்திரி","சரகர்","வாக்படர்"],"correctAnswer":1,"explanation":"இரண்டாம் சந்திரகுப்தரின் அரசவையை அலங்கரித்த நவரத்தினங்களில் ஆயுர்வேத மருத்துவ மேதையான தன்வந்திரியும் ஒருவர் ஆவார். அறுவை சிகிச்சையைப் பற்றி விளக்கிய முதல் இந்தியரான சுஸ்ருதரும், நவநீதகம் எழுதிய மருத்துவ அறிஞர்களும் குப்தர் கால மருத்துவ வளர்ச்சிக்குச் சான்றுகளாகும்.","difficulty":"medium","topic":"குப்தப் பேரரசு"},{"id":45,"subject":"gk","testNumber":1,"question":"மத்திய ஆசியாவிலிருந்து குப்தப் பேரரசின் மீது படையெடுத்து வந்த ஹூணர்களை (Huns) வெற்றிகரமாகத் தடுத்து நிறுத்தி 'குப்தப் பேரரசின் காப்பாளர்' எனப் போற்றப்பட்டவர் யார்?","options":["புருகுப்தர்","பானுகுப்தர்","ஸ்கந்தகுப்தர்","கடோத்கஜர்"],"correctAnswer":2,"explanation":"முதலாம் குமாரகுப்தரின் மகனான ஸ்கந்தகுப்தர், மத்திய ஆசியாவிலிருந்து படையெடுத்து வந்த வலிமையான ஹூணர்களைத் தோற்கடித்துப் பேரரசைக் காப்பாற்றினார். இருப்பினும், ஹூணர்களின் தொடர் படையெடுப்புகள் பிற்காலத்தில் குப்தப் பேரரசின் வீழ்ச்சிக்கு முக்கியக் காரணமாயின.","difficulty":"medium","topic":"குப்தப் பேரரசு"},{"id":46,"subject":"gk","testNumber":1,"question":"தில்லியில் உள்ள குதுப்மினார் வளாகத்தில் இன்றளவும் துருப்பிடிக்காமல் நிற்கும் மெஹ்ராலி இரும்புத் தூண் எந்த குப்த மன்னரின் காலத்தைச் சேர்ந்ததாகக் கருதப்படுகிறது?","options":["ஸ்ரீகுப்தர்","இரண்டாம் சந்திரகுப்தர்","புதகுப்தர்","முதலாம் சந்திரகுப்தர்"],"correctAnswer":1,"explanation":"தில்லியின் மெஹ்ராலியில் அமைந்துள்ள சுமார் 7 மீட்டர் உயரமும் 6 டன்னுக்கு மேல் எடையும் கொண்ட இரும்புத் தூண் 'சந்திரா' என்ற அரசரைக் குறிப்பிடுகிறது; இது இரண்டாம் சந்திரகுப்தரைக் குறிப்பதாக வரலாற்றாசிரியர்கள் கருதுகின்றனர். 1,600 ஆண்டுகளுக்கு மேலாகியும் துருப்பிடிக்காமல் இருப்பது குப்தர் கால உலோகவியலின் உச்சத்திற்குச் சான்றாகும்.","difficulty":"medium","topic":"குப்தப் பேரரசு"},{"id":47,"subject":"gk","testNumber":1,"question":"வர்த்தன வம்சத்தின் சிறந்த அரசரான ஹர்ஷவர்த்தனர் தனது தலைநகரை தானேஸ்வரத்திலிருந்து எந்த நகருக்கு மாற்றினார்?","options":["பாடலிபுத்திரம்","கன்னோசி","அயோத்தி","உஜ்ஜயினி"],"correctAnswer":1,"explanation":"புஷ்யபூதி (வர்த்தன) வம்சத்தின் அரசரான ஹர்ஷவர்த்தனர் கி.பி. 606-இல் அரியணை ஏறி தனது தலைநகரை தானேஸ்வரத்திலிருந்து கன்னோசிக்கு (Kannauj) மாற்றினார். வட இந்தியாவில் ஹர்ஷர் காலத்தில் கன்னோசி மிக முக்கிய அரசியல் மற்றும் பண்பாட்டு மையமாகத் திகழ்ந்தது.","difficulty":"medium","topic":"வர்த்தனர்கள்"},{"id":48,"subject":"gk","testNumber":1,"question":"கலை மற்றும் இலக்கியத்தில் வல்லவரான ஹர்ஷவர்த்தனர் சமஸ்கிருத மொழியில் இயற்றிய மூன்று புகழ்பெற்ற நாடக நூல்கள் யாவை?","options":["மத்தவிலாசப் பிரகசனம், பகவதஜ்ஜுகீயம், கிராதார்ஜுனீயம்","ரத்னாவளி, நாகானந்தம், பிரியதர்சிகா","முத்ரா ராக்ஷசம், தேவிசந்திரகுப்தம், மிருச்சகடிகம்","சாகுந்தலம், மேகதூதம், ரகுவம்சம்"],"correctAnswer":1,"explanation":"ஹர்ஷவர்த்தனர் சிறந்த ஆட்சியாளர் மட்டுமின்றி தலைசிறந்த எழுத்தாளரும் ஆவார். இவர் சமஸ்கிருத மொழியில் 'ரத்னாவளி', 'நாகானந்தம்' மற்றும் 'பிரியதர்சிகா' ஆகிய மூன்று புகழ்பெற்ற நாடக நூல்களை இயற்றினார்.","difficulty":"medium","topic":"வர்த்தனர்கள்"},{"id":49,"subject":"gk","testNumber":1,"question":"ஹர்ஷவர்த்தனரின் அவைக்களப் புலவரான பாணபட்டர் எழுதிய ஹர்ஷரின் வாழ்க்கை வரலாற்று நூல் எது?","options":["பிருத்விராஜ ராசோ","ஹர்ஷசரிதம்","விக்ரமாங்கதேவ சரிதம்","ராஜதரங்கிணி"],"correctAnswer":1,"explanation":"ஹர்ஷவர்த்தனரின் அரசவைப் புலவரான பாணபட்டர் சமஸ்கிருத மொழியில் 'ஹர்ஷசரிதம்' என்ற வரலாற்று நூலையும், 'காதம்பரி' என்ற உரைநடைக் காவியத்தையும் இயற்றினார். ஹர்ஷரின் ஆட்சி மற்றும் வாழ்க்கையை அறிய 'ஹர்ஷசரிதம்' மிக முக்கிய ஆதாரமாகும்.","difficulty":"medium","topic":"வர்த்தனர்கள்"},{"id":50,"subject":"gk","testNumber":1,"question":"'பயணிகளின் இளவரசர்' எனப் போற்றப்படும் சீனப் பயணி யுவான் சுவாங் (Hiuen Tsang) ஹர்ஷர் கால இந்தியாவைப் பற்றி எழுதிய பயணக் குறிப்பு நூல் எது?","options":["சி-யூ-கி","ஃபோ-குவோ-கி","ரெஹ்லா","தஹ்கீக்-இ-ஹிந்த்"],"correctAnswer":0,"explanation":"ஹர்ஷவர்த்தனரின் ஆட்சிக்காலத்தில் இந்தியா வந்த சீன பௌத்தத் துறவியான யுவான் சுவாங், நாளந்தா பல்கலைக்கழகத்தில் கல்வி கற்றார். இவர் தனது இந்தியப் பயண அனுபவங்களை 'சி-யூ-கி' (Si-Yu-Ki — மேற்கு உலகின் குறிப்புகள்) என்ற நூலில் விரிவாகப் பதிவு செய்துள்ளார்.","difficulty":"easy","topic":"வர்த்தனர்கள்"},{"id":51,"subject":"gk","testNumber":1,"question":"நர்மதை நதிக்கரையில் நடைபெற்ற போரில் ஹர்ஷவர்த்தனரைத் தோற்கடித்து 'பரமேஸ்வரன்' என்ற பட்டத்தைச் சூடிக்கொண்ட சாளுக்கிய மன்னர் யார்?","options":["கீர்த்திவர்மன்","இரண்டாம் புலிகேசி","முதலாம் புலிகேசி","விக்ரமாதித்யன்"],"correctAnswer":1,"explanation":"வாதாபி சாளுக்கிய மன்னரான இரண்டாம் புலிகேசி, நர்மதை ஆற்றங்கரையில் ஹர்ஷவர்த்தனரின் தென்னிந்தியப் படையெடுப்பைத் தடுத்து நிறுத்தி அவரைத் தோற்கடித்தார். இந்த வெற்றியைப் பற்றி இரண்டாம் புலிகேசியின் அவைக்களப் புலவர் ரவிகீர்த்தி இயற்றிய 'ஐஹோளே கல்வெட்டு' விவரிக்கிறது.","difficulty":"hard","topic":"வர்த்தனர்கள்"},{"id":52,"subject":"gk","testNumber":1,"question":"குப்தப் பேரரசின் காலத்தில் வெளியிடப்பட்ட தங்க நாணயங்கள் எவ்வாறு அழைக்கப்பட்டன?","options":["பணம்","தினாரா","ரூபகா","நிஷ்கா"],"correctAnswer":1,"explanation":"குப்த மன்னர்கள் மிக உயர்ந்த தரத்தில் அதிக அளவிலான தங்க நாணயங்களை வெளியிட்டனர்; அவை 'தினாரா' (Dinara) என அழைக்கப்பட்டன. குப்தர்கள் வெளியிட்ட வெள்ளி நாணயங்கள் 'ரூபகா' எனப்பட்டன.","difficulty":"hard","topic":"குப்தப் பேரரசு"},{"id":53,"subject":"gk","testNumber":1,"question":"1206-இல் தில்லி சுல்தானியத்தின் அடிமை வம்சத்தைத் (மம்லுக் வம்சம்) தோற்றுவித்தவரும், கொடைத்தன்மைக்காக 'லாக் பக்ஷ்' (லட்சங்களைக் கொடுப்பவர்) என அழைக்கப்பட்டவருமான அரசர் யார்?","options":["குத்புதீன் ஐபக்","கியாசுதீன் பால்பன்","இல்துமிஷ்","முகமது கோரி"],"correctAnswer":0,"explanation":"முகமது கோரியின் தளபதியும் அடிமையுமான குத்புதீன் ஐபக் 1206-இல் அடிமை வம்ச ஆட்சியை நிறுவினார். இவர் லாகூரைத் தலைநகராகக் கொண்டு ஆட்சி செய்தார்; தாராளமாகக் கொடை வழங்கியதால் 'லாக் பக்ஷ்' எனப் போற்றப்பட்டார். 1210-இல் சௌகான் (போலோ) விளையாட்டின்போது குதிரையிலிருந்து விழுந்து உயிரிழந்தார்.","difficulty":"easy","topic":"தில்லி சுல்தானியம் - அடிமை வம்சம்"},{"id":54,"subject":"gk","testNumber":1,"question":"தில்லியில் உள்ள உலகப் புகழ்பெற்ற 'குதுப்மினார்' கோபுரத்தின் கட்டுமானப் பணியைத் தொடங்கியவர் மற்றும் அதனை முழுமையாகக் கட்டி முடித்தவர் முறையே யார்?","options":["குத்புதீன் ஐபக் மற்றும் அலாவுதீன் கில்ஜி","இல்துமிஷ் மற்றும் பால்பன்","குத்புதீன் ஐபக் மற்றும் இல்துமிஷ்","அலாவுதீன் கில்ஜி மற்றும் பெரோஸ் ஷா துக்ளக்"],"correctAnswer":2,"explanation":"சூபி துறவி குவாஜா குத்புதீன் பக்தியார் காக்கியின் நினைவாக குத்புதீன் ஐபக் குதுப்மினார் கட்டுமானத்தைத் தொடங்கினார். அவரது மருமகனான இல்துமிஷ் அதன் கட்டுமானப் பணிகளை நிறைவு செய்தார்; பிற்காலத்தில் மின்னலால் சேதமடைந்த மேல் தளத்தைப் பெரோஸ் ஷா துக்ளக் சீரமைத்தார்.","difficulty":"easy","topic":"தில்லி சுல்தானியம் - அடிமை வம்சம்"},{"id":55,"subject":"gk","testNumber":1,"question":"துருக்கிய பிரபுக்களின் 'நாற்பதின்மர் குழுவை' (சஹல்கானி) அமைத்து, 'இக்தா' நிலமானிய முறையையும் 'டங்கா' வெள்ளி நாணயத்தையும் அறிமுகப்படுத்திய தில்லி சுல்தான் யார்?","options":["இல்துமிஷ்","முகமது பின் துக்ளக்","பால்பன்","குத்புதீன் ஐபக்"],"correctAnswer":0,"explanation":"தில்லி சுல்தானியத்தின் உண்மையான நிறுவனர் எனக் கருதப்படும் சம்சுதீன் இல்துமிஷ், தில்லியைத் தலைநகராக்கி 'சஹல்கானி' (நாற்பதின்மர் குழு) என்ற துருக்கியப் பிரபுக்கள் குழுவை உருவாக்கினார். இவர் படைத்தளபதிகளுக்கு ஊதியத்திற்குப் பதிலாக நிலம் வழங்கும் 'இக்தா' முறையையும், 'டங்கா' (வெள்ளி) மற்றும் 'ஜிடால்' (செப்பு) நாணயங்களையும் அறிமுகப்படுத்தினார்.","difficulty":"medium","topic":"தில்லி சுல்தானியம் - அடிமை வம்சம்"},{"id":56,"subject":"gk","testNumber":1,"question":"தில்லி சுல்தானியத்தின் அரியணையில் அமர்ந்து ஆட்சி புரிந்த முதல் மற்றும் ஒரே பெண் அரசி யார்?","options":["ரசியா சுல்தானா","நூர்ஜகான்","குல்பதன் பேகம்","சாந்த் பீவி"],"correctAnswer":0,"explanation":"இல்துமிஷின் மகளான ரசியா சுல்தானா கி.பி. 1236 முதல் 1240 வரை தில்லி சுல்தானியத்தை ஆட்சி செய்த முதல் மற்றும் ஒரே பெண் ஆட்சியாளர் ஆவார். துருக்கியப் பிரபுக்களின் எதிர்ப்பால் 1240-இல் இவர் சதித் திட்டத்தால் கொல்லப்பட்டார்.","difficulty":"easy","topic":"தில்லி சுல்தானியம் - அடிமை வம்சம்"},{"id":57,"subject":"gk","testNumber":1,"question":"'நாற்பதின்மர் குழுவை' (சஹல்கானி) முற்றிலும் ஒழித்து, 'சிஜ்தா' மற்றும் 'பைபோஸ்' ஆகிய பாரசீக அரசவை மரபுகளை அறிமுகப்படுத்திய அடிமை வம்ச சுல்தான் யார்?","options":["நசிருதீன் முகமது","இல்துமிஷ்","கியாசுதீன் பால்பன்","கைகுபாத்"],"correctAnswer":2,"explanation":"கியாசுதீன் பால்பன் 'தெய்வீக உரிமைக் கோட்பாட்டை' வலியுறுத்தித் தன்னை 'ஜில்-இ-இலாஹி' (கடவுளின் நிழல்) என அறிவித்துக் கொண்டார். இவர் பிரபுக்களின் அதிகாரத்தை ஒடுக்க நாற்பதின்மர் குழுவை ஒழித்தார்; மேலும் 'சிஜ்தா' (மண்டியிட்டு வணங்குதல்), 'பைபோஸ்' (அரசரின் பாதங்களை முத்தமிடுதல்) மற்றும் 'நவ்ரோஸ்' (பாரசீகப் புத்தாண்டு) ஆகியவற்றை அறிமுகப்படுத்தினார்.","difficulty":"medium","topic":"தில்லி சுல்தானியம் - அடிமை வம்சம்"},{"id":58,"subject":"gk","testNumber":1,"question":"1290-ஆம் ஆண்டு அடிமை வம்சத்திற்கு முடிவு கட்டி தில்லி சுல்தானியத்தில் கில்ஜி வம்சத்தைத் தோற்றுவித்தவர் யார்?","options":["அலாவுதீன் கில்ஜி","குஸ்ரு கான்","ஜலாலுதீன் கில்ஜி","முபாரக் ஷா கில்ஜி"],"correctAnswer":2,"explanation":"1290-இல் ஜலாலுதீன் பெரோஸ் கில்ஜி கில்ஜி வம்சத்தைத் தோற்றுவித்தார். இவர் கருணை உள்ளம் கொண்டவராக இருந்ததால் 'கருணை உள்ளம் கொண்ட ஜலாலுதீன்' எனப்பட்டார். 1296-இல் அவரது மருமகன் அலாவுதீன் கில்ஜியால் இவர் கொல்லப்பட்டார்.","difficulty":"medium","topic":"தில்லி சுல்தானியம் - கில்ஜி வம்சம்"},{"id":59,"subject":"gk","testNumber":1,"question":"படைவீரர்களின் அடையாளப் பதிவான 'ஹுலியா' (சேரா) மற்றும் குதிரைகளுக்குச் சூடுபோடும் 'தாக்' (Dagh) ஆகிய இராணுவச் சீர்திருத்தங்களை அறிமுகப்படுத்திய தில்லி சுல்தான் யார்?","options":["பெரோஸ் ஷா துக்ளக்","அலாவுதீன் கில்ஜி","பால்பன்","இல்துமிஷ்"],"correctAnswer":1,"explanation":"நிரந்தரப் படையை உருவாக்கிப் படைவீரர்களுக்குப் பணமாக ஊதியம் வழங்கிய முதல் தில்லி சுல்தான் அலாவுதீன் கில்ஜி ஆவார். படைத்துறையில் ஊழலைத் தடுக்கக் குதிரைகளுக்கு முத்திரையிடும் 'தாக்' முறையையும், வீரர்களின் முழு விவரங்களைப் பதிவு செய்யும் 'ஹுலியா' (சேரா) முறையையும் இவர் நடைமுறைப்படுத்தினார்.","difficulty":"medium","topic":"தில்லி சுல்தானியம் - கில்ஜி வம்சம்"},{"id":60,"subject":"gk","testNumber":1,"question":"அலாவுதீன் கில்ஜியின் தென்னிந்தியப் படையெடுப்புகளுக்குத் தலைமை தாங்கி, தேவகிரி, வாரங்கல், துவாரசமுத்திரம் மற்றும் மதுரை வரை படையெடுத்த தளபதி யார்?","options":["ஜாபர் கான்","மாலிக் காபூர்","உலுக் கான்","நுஸ்ரத் கான்"],"correctAnswer":1,"explanation":"குஜராத் படையெடுப்பின்போது ஆயிரம் தினார்களுக்கு வாங்கப்பட்டதால் 'ஹசார் தினாரி' என அழைக்கப்பட்ட மாலிக் காபூர், அலாவுதீன் கில்ஜியின் நம்பிக்கைக்குரிய தளபதியாக உயர்ந்தார். இவர் தேவகிரி யாதவர்கள், வாரங்கல் காகதீயர்கள், துவாரசமுத்திர ஹொய்சாளர்கள் மற்றும் மதுரை பாண்டியர்கள் மீது படையெடுத்துப் பெரும் செல்வத்தைத் தில்லிக்குக் கொண்டு சென்றார்.","difficulty":"easy","topic":"தில்லி சுல்தானியம் - கில்ஜி வம்சம்"},{"id":61,"subject":"gk","testNumber":1,"question":"அலாவுதீன் கில்ஜி நடைமுறைப்படுத்திய அங்காடிக் கட்டுப்பாட்டு (விலை நிர்ணய) முறையைக் கண்காணிக்க நியமிக்கப்பட்ட தலைமை அதிகாரி எவ்வாறு அழைக்கப்பட்டார்?","options":["ஷானா-இ-மண்டி","திவான்-இ-இன்ஷா","காஜி-உல்-குஜாத்","திவான்-இ-ஆரிஸ்"],"correctAnswer":0,"explanation":"படைவீரர்களுக்குக் குறைந்த விலையில் அத்தியாவசியப் பொருட்கள் கிடைப்பதை உறுதி செய்ய அலாவுதீன் கில்ஜி அங்காடிக் கட்டுப்பாட்டு முறையைக் கொண்டு வந்தார். சந்தையில் விலைவாசி மற்றும் எடைகளைக் கண்காணிக்க 'ஷானா-இ-மண்டி' என்ற அதிகாரியும், 'திவான்-இ-ரியாசத்' என்ற துறையும் செயல்பட்டன.","difficulty":"hard","topic":"தில்லி சுல்தானியம் - கில்ஜி வம்சம்"},{"id":62,"subject":"gk","testNumber":1,"question":"'இந்தியாவின் கிளி' (தூதி-இ-ஹிந்த்) எனப் போற்றப்பட்டவரும், அலாவுதீன் கில்ஜி உள்ளிட்ட பல தில்லி சுல்தான்களின் அவையை அலங்கரித்தவருமான பாரசீகக் கவிஞர் யார்?","options":["அல்-பரூனி","ஜியாவுதீன் பரணி","அமீர் குஸ்ரு","மின்ஹஜ்-உஸ்-சிராஜ்"],"correctAnswer":2,"explanation":"அமீர் குஸ்ரு பாரசீக மற்றும் உருது இலக்கியங்களின் வளர்ச்சிக்குப் பெரும் பங்காற்றிய கவிஞரும் இசைக்கலைஞரும் ஆவார். சித்தார் மற்றும் தபேலா இசைக்கருவிகளையும் 'கவ்வாலி' இசையையும் உருவாக்கியதில் இவருக்குப் பெரும் பங்கு உண்டு; இவர் 'இந்தியாவின் கிளி' (Tuti-e-Hind) எனப் போற்றப்படுகிறார்.","difficulty":"medium","topic":"தில்லி சுல்தானியம் - கில்ஜி வம்சம்"},{"id":63,"subject":"gk","testNumber":1,"question":"1320-ஆம் ஆண்டு தில்லி சுல்தானியத்தில் துக்ளக் வம்சத்தை நிறுவிய கியாசுதீன் துக்ளக்கின் இயற்பெயர் என்ன?","options":["ஜுனா கான்","பஹ்லுல் கான்","காசி மாலிக்","உலுக் கான்"],"correctAnswer":2,"explanation":"கில்ஜி வம்சத்தின் இறுதி ஆட்சியாளரான குஸ்ரு கானைத் தோற்கடித்து 1320-இல் துக்ளக் வம்சத்தைத் தோற்றுவித்த கியாசுதீன் துக்ளக்கின் இயற்பெயர் 'காசி மாலிக்' ஆகும். இவர் தில்லிக்கு அருகில் 'துக்ளகாபாத்' என்ற புதிய நகரத்தை நிர்மாணித்தார்.","difficulty":"hard","topic":"தில்லி சுல்தானியம் - துக்ளக் வம்சம்"},{"id":64,"subject":"gk","testNumber":1,"question":"தலைநகரை தில்லியிலிருந்து தேவகிரிக்கு (தௌலதாபாத்) மாற்றுதல் மற்றும் செப்பு அடையாள நாணயங்களை வெளியிடுதல் ஆகிய தோல்வியடைந்த திட்டங்களைச் செயல்படுத்திய சுல்தான் யார்?","options":["அலாவுதீன் கில்ஜி","முகமது பின் துக்ளக்","கியாசுதீன் துக்ளக்","பெரோஸ் ஷா துக்ளக்"],"correctAnswer":1,"explanation":"கற்றறிந்த மேதையாகத் திகழ்ந்தபோதும் அவசர முடிவுகளால் தோல்வியடைந்த முகமது பின் துக்ளக் (இயற்பெயர்: ஜுனா கான்), 1327-இல் தலைநகரைத் தில்லியிலிருந்து தேவகிரிக்கு (தௌலதாபாத்) மாற்றினார். மேலும் வெள்ளிக்குப் பதிலாகச் செப்பு அடையாள நாணயங்களை வெளியிட்டதால் கள்ள நாணயங்கள் பெருகிப் பொருளாதாரம் பாதிக்கப்பட்டது.","difficulty":"easy","topic":"தில்லி சுல்தானியம் - துக்ளக் வம்சம்"},{"id":65,"subject":"gk","testNumber":1,"question":"முகமது பின் துக்ளக் வேளாண்மையை மேம்படுத்துவதற்காகவும் விவசாயிகளுக்குத் 'தக்காவி' கடன்களை வழங்குவதற்காகவும் உருவாக்கிய தனித் துறையின் பெயர் என்ன?","options":["திவான்-இ-கைரத்","திவான்-இ-முஸ்தக்ராஜ்","திவான்-இ-பந்தகன்","திவான்-இ-அமீர்-கோஹி"],"correctAnswer":3,"explanation":"முகமது பின் துக்ளக் தரிசு நிலங்களை விளைநிலங்களாக மாற்றுவதற்கும் வேளாண்மையை மேம்படுத்துவதற்கும் 'திவான்-இ-அமீர்-கோஹி' என்ற வேளாண்மைத் துறையை உருவாக்கினார். இதன் மூலம் விவசாயிகளுக்கு 'தக்காவி' (Taccavi) எனப்படும் வேளாண் கடன்கள் வழங்கப்பட்டன.","difficulty":"hard","topic":"தில்லி சுல்தானியம் - துக்ளக் வம்சம்"},{"id":66,"subject":"gk","testNumber":1,"question":"முகமது பின் துக்ளக்கின் ஆட்சிக்காலத்தில் இந்தியா வருகை தந்த மொராக்கோ நாட்டுப் பயணி மற்றும் அவர் எழுதிய பயண நூல் முறையே எவை?","options":["இபின் பதூதா மற்றும் ரெஹ்லா","அப்துர் ரசாக் மற்றும் மத்லா-உஸ்-சாதைன்","அல்-பரூனி மற்றும் கிதாப்-உல்-ஹிந்த்","நிக்கோலோ கோண்டி மற்றும் சபார்நாமா"],"correctAnswer":0,"explanation":"வட ஆப்பிரிக்காவின் மொராக்கோ நாட்டைச் சேர்ந்த பயணி இபின் பதூதா 1333-இல் முகமது பின் துக்ளக்கின் ஆட்சிக்காலத்தில் இந்தியா வந்தார். சுல்தான் இவரைத் தில்லியின் 'காஜி' (நீதிபதி) ஆக நியமித்தார்; இவர் தனது இந்தியப் பயண அனுபவங்களை 'ரெஹ்லா' (பயணங்கள்) என்ற நூலில் எழுதியுள்ளார்.","difficulty":"medium","topic":"தில்லி சுல்தானியம் - துக்ளக் வம்சம்"},{"id":67,"subject":"gk","testNumber":1,"question":"ஏழைகளுக்கு உதவ 'திவான்-இ-கைரத்', அடிமைகள் நலனுக்காக 'திவான்-இ-பந்தகன்' மற்றும் இலவச மருத்துவமனையான 'தாருல் ஷிபா' ஆகியவற்றை அமைத்த தில்லி சுல்தான் யார்?","options":["கியாசுதீன் துக்ளக்","முகமது பின் துக்ளக்","பெரோஸ் ஷா துக்ளக்","சிக்கந்தர் லோடி"],"correctAnswer":2,"explanation":"மக்கள் நலப் பணிகளுக்குப் பெயர் பெற்ற பெரோஸ் ஷா துக்ளக், ஏழைகள் மற்றும் ஆதரவற்றோருக்கு உதவ 'திவான்-இ-கைரத்' என்ற அறக்கட்டளைத் துறையையும், அடிமைகளுக்காக 'திவான்-இ-பந்தகன்' துறையையும், வேலைவாய்ப்பு அலுவலகத்தையும் அமைத்தார். மேலும் வேளாண்மைக்காகப் பல நீர்ப்பாசனக் கால்வாய்களை வெட்டினார்.","difficulty":"medium","topic":"தில்லி சுல்தானியம் - துக்ளக் வம்சம்"},{"id":68,"subject":"gk","testNumber":1,"question":"தில்லி சுல்தானிய வரலாற்றில் பிராமணர்கள் மீதும் முதன்முதலாக 'ஜிசியா' வரியை விதித்த சுல்தான் யார்?","options":["இப்ராஹிம் லோடி","பெரோஸ் ஷா துக்ளக்","குத்புதீன் ஐபக்","அலாவுதீன் கில்ஜி"],"correctAnswer":1,"explanation":"இஸ்லாமியச் சட்டங்களின்படி ஆட்சி நடத்த முயன்ற பெரோஸ் ஷா துக்ளக், முந்தைய சுல்தான்களால் விலக்களிக்கப்பட்டிருந்த பிராமணர்கள் மீதும் முதன்முறையாக ஜிசியா வரியை விதித்தார். மேலும் இஸ்லாமியச் சட்டப்படி கராஜ், கம்ஸ், ஜிசியா, ஜகாத் ஆகிய நான்கு வரிகளை மட்டுமே வசூலித்தார்.","difficulty":"hard","topic":"தில்லி சுல்தானியம் - துக்ளக் வம்சம்"},{"id":69,"subject":"gk","testNumber":1,"question":"கி.பி. 1398-இல் சாமர்கண்டிலிருந்து இந்தியா மீது படையெடுத்து தில்லியைச் சூறையாடிய மங்கோலிய-துருக்கியப் படையெடுப்பாளர் யார்?","options":["நாதிர்ஷா","செங்கிஸ்கான்","தைமூர்","முகமது கஜினி"],"correctAnswer":2,"explanation":"துக்ளக் வம்சத்தின் கடைசி அரசரான நசிருதீன் முகமது ஷா ஆட்சிக்காலத்தில் 1398-ஆம் ஆண்டு மத்திய ஆசியாவின் சாமர்கண்ட் அரசரான தைமூர் இந்தியா மீது படையெடுத்தார். இவர் தில்லியைக் கடுமையாகச் சூறையாடியதோடு, திரும்பிச் செல்லும்போது கிசிர்கானைத் தனது பிரதிநிதியாக நியமித்துச் சென்றார்.","difficulty":"medium","topic":"தில்லி சுல்தானியம் - துக்ளக் வம்சம்"},{"id":70,"subject":"gk","testNumber":1,"question":"தில்லி சுல்தானியத்தில் 1414-ஆம் ஆண்டு சையது வம்சத்தைத் தோற்றுவித்தவர் யார்?","options":["முபாரக் ஷா","ஆலம் ஷா","பஹ்லுல் லோடி","கிசிர்கான்"],"correctAnswer":3,"explanation":"தைமூரின் பிரதிநிதியாக முல்தான் மற்றும் லாகூர் பகுதிகளை ஆட்சி செய்த கிசிர்கான் 1414-இல் தில்லியைக் கைப்பற்றி சையது வம்சத்தைத் தோற்றுவித்தார். இவர் 'சுல்தான்' என்ற பட்டத்தை ஏற்காமல் 'ராயத்-இ-ஆலா' என்ற பட்டத்துடன் ஆட்சி புரிந்தார்.","difficulty":"medium","topic":"தில்லி சுல்தானியம் - சையது & லோடி வம்சம்"},{"id":71,"subject":"gk","testNumber":1,"question":"1504-ஆம் ஆண்டு ஆக்ரா நகரத்தை நிறுவி அதனைத் தனது தலைநகராக்கிய லோடி வம்சத்தின் சிறந்த அரசர் யார்?","options":["பஹ்லுல் லோடி","தௌலத்கான் லோடி","சிக்கந்தர் லோடி","இப்ராஹிம் லோடி"],"correctAnswer":2,"explanation":"ஆப்கானிய வம்சமான லோடி வம்சத்தின் மிகச்சிறந்த அரசர் சிக்கந்தர் லோடி ஆவார். இவர் 1504-இல் யமுனை நதிக்கரையில் ஆக்ரா நகரத்தை நிறுவினார்; மேலும் நிலத்தை அளப்பதற்கு 'கஜ்-இ-சிக்கந்தரி' என்ற அளவுகோலை அறிமுகப்படுத்தினார்.","difficulty":"medium","topic":"தில்லி சுல்தானியம் - சையது & லோடி வம்சம்"},{"id":72,"subject":"gk","testNumber":1,"question":"கி.பி. 1526 ஏப்ரல் 21-ஆம் நாள் நடைபெற்ற முதல் பானிபட் போரில் பாபர் யாரைத் தோற்கடித்து தில்லி சுல்தானியத்திற்கு முடிவு கட்டினார்?","options":["இப்ராஹிம் லோடி","ராணா சங்கா","சிக்கந்தர் லோடி","ஷெர்ஷா சூரி"],"correctAnswer":0,"explanation":"1526-ஆம் ஆண்டு நடைபெற்ற முதல் பானிபட் போரில் ஜாகிருதீன் முகமது பாபர் தனது பீரங்கிப் படை மற்றும் 'துலுக்மா' போர் உத்தியைப் பயன்படுத்தி தில்லி சுல்தான் இப்ராஹிம் லோடியைத் தோற்கடித்துக் கொன்றார். இதன் மூலம் தில்லி சுல்தானியம் முடிவுக்கு வந்து இந்தியாவில் முகலாயப் பேரரசு நிறுவப்பட்டது.","difficulty":"easy","topic":"தில்லி சுல்தானியம் - சையது & லோடி வம்சம்"},{"id":73,"subject":"gk","testNumber":1,"question":"முகலாயப் பேரரசை நிறுவிய பாபர் தனது சுயசரிதையான 'துசுக்-இ-பாபரி' (பாபர் நாமா) என்ற நூலை எந்த மொழியில் எழுதினார்?","options":["உருது மொழி","பாரசீக மொழி","அரபு மொழி","துருக்கிய மொழி (சகதாய் துருக்கி)"],"correctAnswer":3,"explanation":"பாபர் தனது சுயசரிதையான 'துசுக்-இ-பாபரி' (பாபர் நாமா) என்ற நூலைத் தனது தாய்மொழியான சகதாய் துருக்கிய மொழியில் எழுதினார். அக்பரின் காலத்தில் அப்துர் ரஹீம் கான்-இ-கானான் இந்நூலைப் பாரசீக மொழியில் மொழிபெயர்த்தார்.","difficulty":"medium","topic":"முகலாயப் பேரரசு"},{"id":74,"subject":"gk","testNumber":1,"question":"கி.பி. 1527-ஆம் ஆண்டு ஆக்ராவிற்கு அருகில் நடைபெற்ற கான்வா போரில் பாபர் எந்த ராஜபுத்திர மன்னரைத் தோற்கடித்தார்?","options":["மேதினி ராய்","பிருத்விராஜ் சௌகான்","ராணா பிரதாப்","ராணா சங்கா"],"correctAnswer":3,"explanation":"1527-இல் நடைபெற்ற கான்வா போரில் பாபர் மேவார் மன்னர் ராணா சங்கா தலைமையிலான ராஜபுத்திரக் கூட்டணியைத் தோற்கடித்து 'காசி' என்ற பட்டத்தைப் பெற்றார். அதன்பின் 1528-இல் சந்தேரி போரில் மேதினி ராயையும், 1529-இல் காக்ரா போரில் ஆப்கானியர்களையும் வென்றார்.","difficulty":"medium","topic":"முகலாயப் பேரரசு"},{"id":75,"subject":"gk","testNumber":1,"question":"சௌசா போர் (1539) மற்றும் கன்னோசி (பில்கிராம்) போரில் (1540) ஹுமாயூனைத் தோற்கடித்து தில்லியில் சூர் வம்ச ஆட்சியை நிறுவிய ஆப்கானிய அரசர் யார்?","options":["ஆதில் ஷா","மஹ்மூத் லோடி","ஷெர்ஷா சூரி","இஸ்லாம் ஷா"],"correctAnswer":2,"explanation":"பீகார் ஆட்சியாளரான ஷெர்ஷா சூரி (இயற்பெயர்: பரித்) 1539 சௌசா போரிலும் 1540 கன்னோசி போரிலும் முகலாய மன்னர் ஹுமாயூனைத் தோற்கடித்து சூர் வம்சத்தை நிறுவினார். ஹுமாயூன் 15 ஆண்டுகள் பாரசீகத்தில் தஞ்சமடைந்து 1555-இல் மீண்டும் தில்லியைக் கைப்பற்றினார்.","difficulty":"easy","topic":"முகலாயப் பேரரசு"},{"id":76,"subject":"gk","testNumber":1,"question":"'ரூபியா' என்ற தரமான வெள்ளி நாணயத்தை அறிமுகப்படுத்தியவரும், வங்காளத்தின் சோனார்கானிலிருந்து பெஷாவர் வரை 'கிராண்ட் டிரங்க்' (பெரும் தலைநெடுஞ்சாலை) சாலையைச் சீரமைத்தவருமான ஆட்சியாளர் யார்?","options":["ஜஹாங்கீர்","ஷெர்ஷா சூரி","அக்பர்","பாபர்"],"correctAnswer":1,"explanation":"அக்பரின் நிர்வாகத்திற்கு முன்னோடியாகக் கருதப்படும் ஷெர்ஷா சூரி, 'ரூபியா' என்ற வெள்ளி நாணயத்தையும் 'தாம்' என்ற செப்பு நாணயத்தையும் அறிமுகப்படுத்தினார். இவர் 'சடக்-இ-ஆஸம்' (கிராண்ட் டிரங்க் சாலை) என்ற நெடுஞ்சாலையைச் சீரமைத்து, பயணிகளுக்காகப் பல சத்திரங்களை (சராய்) அமைத்தார்.","difficulty":"easy","topic":"முகலாயப் பேரரசு"},{"id":77,"subject":"gk","testNumber":1,"question":"கி.பி. 1556 நவம்பர் 5-ஆம் நாள் நடைபெற்ற இரண்டாம் பானிபட் போரில் அக்பரின் பாதுகாவலர் பைராம் கான் யாரைத் தோற்கடித்தார்?","options":["ஷெர்ஷா சூரி","ராணா பிரதாப்","ஹெமு","பாஸ் பகதூர்"],"correctAnswer":2,"explanation":"ஹுமாயூனின் மறைவுக்குப் பிறகு ஆதில் ஷா சூரின் தளபதியான ஹெமு (விக்ரமாதித்யா) தில்லியையும் ஆக்ராவையும் கைப்பற்றினார். 1556-இல் நடைபெற்ற இரண்டாம் பானிபட் போரில் அக்பரின் படைத்தளபதி பைராம் கான் ஹெமுவைத் தோற்கடித்து முகலாய ஆட்சியை நிலைநிறுத்தினார்.","difficulty":"easy","topic":"முகலாயப் பேரரசு"},{"id":78,"subject":"gk","testNumber":1,"question":"பேரரசர் அக்பர் அனைத்து சமயங்களின் சிறந்த கருத்துகளையும் ஒருங்கிணைத்து 1582-ஆம் ஆண்டு வெளியிட்ட புதிய சமயக் கோட்பாடு எது?","options":["மஹ்சர் அறிவிப்பு","இபாதத் கானா","தீன்-இலாஹி","சுல்-இ-குல்"],"correctAnswer":2,"explanation":"சமயப் பொறையைக் கடைப்பிடித்த அக்பர் 1575-இல் பதேபூர் சிக்ரியில் 'இபாதத் கானா' (வழிபாட்டுக் கூடம்) அமைத்து அனைத்து சமய அறிஞர்களுடன் விவாதித்தார். அதன் தொடர்ச்சியாக 1582-இல் 'தீன்-இலாஹி' (தெய்வீக நம்பிக்கை) என்ற புதிய கோட்பாட்டை அறிவித்தார்; இதனை ஏற்றுக்கொண்ட ஒரே இந்து அரசவைப் பிரமுகர் பீர்பால் ஆவார்.","difficulty":"easy","topic":"முகலாயப் பேரரசு"},{"id":79,"subject":"gk","testNumber":1,"question":"அக்பர் அறிமுகப்படுத்திய 'மன்சப்தாரி' நிர்வாக முறையில் 'ஜாட்' (Zat) மற்றும் 'சவார்' (Sawar) என்பவை முறையே எவற்றைக் குறிக்கின்றன?","options":["ஜாட் - காலாட்படை எண்ணிக்கை; சவார் - யானைப்படை எண்ணிக்கை","ஜாட் - நில வருவாய்; சவார் - வணிக வரி","ஜாட் - மாகாண ஆளுநர்; சவார் - மாவட்ட நீதிபதி","ஜாட் - அதிகாரியின் தனிப்பட்ட தகுதி மற்றும் ஊதியம்; சவார் - அவர் பராமரிக்க வேண்டிய குதிரைப்படை வீரர்களின் எண்ணிக்கை"],"correctAnswer":3,"explanation":"அக்பர் அறிமுகப்படுத்திய 'மன்சப்தாரி' முறையில் ஒவ்வொரு குடிமை மற்றும் இராணுவ அதிகாரிக்கும் ஒரு தகுதி எண் (மன்சப்) வழங்கப்பட்டது. இதில் 'ஜாட்' என்பது அதிகாரியின் தனிப்பட்ட தகுதி மற்றும் ஊதியத்தையும், 'சவார்' என்பது அவர் பராமரிக்க வேண்டிய குதிரை மற்றும் குதிரைப்படை வீரர்களின் எண்ணிக்கையையும் குறித்தது.","difficulty":"hard","topic":"முகலாயப் பேரரசு"},{"id":80,"subject":"gk","testNumber":1,"question":"அக்பரின் வருவாய் அமைச்சராகப் பணியாற்றி, 10 ஆண்டு சராசரி விளைச்சலை அடிப்படையாகக் கொண்ட 'ஜப்தி' (தஹ்சாலா) நிலவருவாய் முறையை உருவாக்கியவர் யார்?","options":["ராஜா தோடர்மால்","ராஜா பீர்பால்","தான்சேன்","ராஜா மான்சிங்"],"correctAnswer":0,"explanation":"அக்பரின் நவரத்தினங்களில் ஒருவரும் வருவாய் அமைச்சருமான ராஜா தோடர்மால் 'ஜப்தி' அல்லது 'பந்தோபஸ்த்' என்ற நிலவருவாய் முறையைச் சீரமைத்து 1580-இல் 'தஹ்சாலா' முறையை அறிமுகப்படுத்தினார். இதன்படி கடந்த 10 ஆண்டுகளின் சராசரி விளைச்சல் மற்றும் விலையின் அடிப்படையில் விளைச்சலில் மூன்றில் ஒரு பங்கு வரியாக நிர்ணயிக்கப்பட்டது.","difficulty":"medium","topic":"முகலாயப் பேரரசு"},{"id":81,"subject":"gk","testNumber":1,"question":"அக்பரின் அவையிலிருந்த நவரத்தினங்களில் ஒருவரும், 'அக்பர் நாமா' மற்றும் 'அயினி அக்பரி' ஆகிய வரலாற்று நூல்களை எழுதியவருமான அறிஞர் யார்?","options":["அபுல் பாசல்","அப்துர் ரஹீம்","பைசி","அப்துல் காதிர் பதானி"],"correctAnswer":0,"explanation":"அக்பரின் நெருங்கிய நண்பரும் அவைக்கள வரலாற்றாசிரியருமான அபுல் பாசல் பாரசீக மொழியில் மூன்று தொகுதிகளைக் கொண்ட 'அக்பர் நாமா' என்ற நூலை எழுதினார். அதன் மூன்றாவது தொகுதியான 'அயினி அக்பரி' அக்பரின் ஆட்சிமுறை, நிர்வாகம், இராணுவம் மற்றும் புள்ளிவிவரங்களை விரிவாகத் தருகிறது.","difficulty":"easy","topic":"முகலாயப் பேரரசு"},{"id":82,"subject":"gk","testNumber":1,"question":"மக்கள் எவ்விதத் தடையுமின்றித் தங்களின் குறைகளைத் தெரிவிக்க ஆக்ரா கோட்டையில் தங்க மணியுடன் கூடிய 'நீதிச் சங்கிலி'யை (Chain of Justice) நிறுவிய முகலாயப் பேரரசர் யார்?","options":["ஜஹாங்கீர்","அக்பர்","ஹுமாயூன்","ஷாஜகான்"],"correctAnswer":0,"explanation":"அக்பரின் மகனான ஜஹாங்கீர் (இயற்பெயர்: சலீம்) தனது நீதி நிர்வாகத்திற்காக ஆக்ரா கோட்டையிலிருந்து யமுனை நதிக்கரை வரை 60 மணிகளைக் கொண்ட 'நீதிச் சங்கிலி'யை (ஜஞ்சீர்-இ-அடில்) அமைத்தார். மேலும் இவர் 'துசுக்-இ-ஜஹாங்கீரி' என்ற சுயசரிதையைப் பாரசீக மொழியில் எழுதினார்.","difficulty":"medium","topic":"முகலாயப் பேரரசு"},{"id":83,"subject":"gk","testNumber":1,"question":"இங்கிலாந்து மன்னர் முதலாம் ஜேம்ஸின் தூதுவராக 1615-இல் ஜஹாங்கீரின் அரசவைக்கு வருகை தந்து, சூரத்தில் ஆங்கிலேய வணிகத் தலம் அமைக்க அனுமதி பெற்றவர் யார்?","options":["கேப்டன் வில்லியம் ஹாக்கின்ஸ்","ரால்ஃப் ஃபிட்ச்","பிரான்சிஸ் டே","சர் தாமஸ் ரோ"],"correctAnswer":3,"explanation":"1608-இல் கேப்டன் வில்லியம் ஹாக்கின்ஸ் ஜஹாங்கீரின் அவைக்கு வந்தபோதும் அவரால் நிரந்தர வணிக அனுமதி பெற முடியவில்லை. பின்னர் 1615-இல் முதலாம் ஜேம்ஸின் அதிகாரப்பூர்வத் தூதுவராக வந்த சர் தாமஸ் ரோ, சூரத் உள்ளிட்ட பகுதிகளில் ஆங்கிலேயக் கிழக்கிந்தியக் கம்பெனி வணிகத் தலங்களை அமைக்க ஜஹாங்கீரிடமிருந்து அனுமதி பெற்றார்.","difficulty":"medium","topic":"முகலாயப் பேரரசு"},{"id":84,"subject":"gk","testNumber":1,"question":"முகலாயக் கட்டடக்கலையின் 'பொற்காலம்' எனப் போற்றப்படும் ஷாஜகானின் ஆட்சியில், ஆக்ராவில் கட்டப்பட்ட தாஜ்மஹாலின் தலைமைக் கட்டடக்கலைஞர் யார்?","options":["மிர் அப்துல் கரீம்","உஸ்தாத் அகமது லஹோரி","உஸ்தாத் மன்சூர்","அபுல் ஹசன்"],"correctAnswer":1,"explanation":"ஷாஜகான் தனது மனைவி மும்தாஜ் மஹாலின் நினைவாக யமுனை நதிக்கரையில் வெள்ளைப் பளிங்குக் கற்களால் தாஜ்மஹாலைக் கட்டினார். இதன் தலைமைக் கட்டடக்கலைஞராகப் பாரசீக-இந்தியக் கலைஞர் உஸ்தாத் அகமது லஹோரி பணியாற்றினார்; இது இந்திய-பாரசீக-இஸ்லாமியக் கட்டடக்கலையின் உச்சமாகத் திகழ்கிறது.","difficulty":"medium","topic":"முகலாயப் பேரரசு"},{"id":85,"subject":"gk","testNumber":1,"question":"'ஆலம்கீர்' (உலகை வெல்பவர்) என்ற பட்டத்தைச் சூடிக்கொண்டு, 1679-ஆம் ஆண்டு ஜிசியா வரியை மீண்டும் விதித்த முகலாயப் பேரரசர் யார்?","options":["ஷாஜகான்","ஔரங்கசீப்","ஜஹாங்கீர்","பகதூர் ஷா"],"correctAnswer":1,"explanation":"ஷாஜகானின் மகனான ஔரங்கசீப் 1658-இல் அரியணை ஏறி 'ஆலம்கீர்' (உலகை வெல்பவர்) என்ற பட்டத்தைச் சூடிக்கொண்டார். அக்பர் நீக்கிய ஜிசியா வரியை 1679-இல் இவர் மீண்டும் விதித்தார்; மேலும் தனது எளிய வாழ்க்கைக்காக 'ஜிந்தா பிர்' (வாழும் துறவி) எனவும் அழைக்கப்பட்டார்.","difficulty":"medium","topic":"முகலாயப் பேரரசு"},{"id":86,"subject":"gk","testNumber":1,"question":"1336-ஆம் ஆண்டு துறவி வித்யாரண்யரின் வழிகாட்டுதலுடன் துங்கபத்திரை நதிக்கரையில் விஜயநகரப் பேரரசை நிறுவிய சகோதரர்கள் யார்?","options":["கிருஷ்ணதேவராயர் மற்றும் அச்சுதராயர்","முதலாம் ஹரிஹரர் மற்றும் புக்கர்","திருமலை மற்றும் ராமராயர்","சாளுவ நரசிம்மர் மற்றும் வீர நரசிம்மர்"],"correctAnswer":1,"explanation":"சங்கமரின் புதல்வர்களான முதலாம் ஹரிஹரர் மற்றும் புக்கர் ஆகிய சகோதரர்கள் சிருங்கேரி மடத் தலைவர் வித்யாரண்யரின் வழிகாட்டுதலுடன் 1336-இல் துங்கபத்திரை நதியின் தென்கரையில் விஜயநகரப் பேரரசை நிறுவினர். இவர்கள் தொடங்கிய முதல் வம்சம் 'சங்கம வம்சம்' எனப்படுகிறது.","difficulty":"easy","topic":"விஜயநகரப் பேரரசு"},{"id":87,"subject":"gk","testNumber":1,"question":"விஜயநகரப் பேரரசை அடுத்தடுத்து ஆட்சி செய்த நான்கு வம்சங்களின் சரியான காலவரிசை எது?","options":["துளுவ – சங்கம – சாளுவ – ஆரவீடு","சாளுவ – சங்கம – துளுவ – ஆரவீடு","சங்கம – சாளுவ – துளுவ – ஆரவீடு","சங்கம – துளுவ – சாளுவ – ஆரவீடு"],"correctAnswer":2,"explanation":"விஜயநகரப் பேரரசை முறையே சங்கம வம்சம் (1336–1485), சாளுவ வம்சம் (1485–1505), துளுவ வம்சம் (1505–1570) மற்றும் ஆரவீடு வம்சம் (1570–1646) ஆகிய நான்கு வம்சங்கள் ஆட்சி செய்தன. இவற்றில் துளுவ வம்சத்தைச் சேர்ந்த கிருஷ்ணதேவராயர் மிகச்சிறந்த அரசராகத் திகழ்ந்தார்.","difficulty":"hard","topic":"விஜயநகரப் பேரரசு"},{"id":88,"subject":"gk","testNumber":1,"question":"விஜயநகரப் பேரரசின் தலைசிறந்த மன்னரான கிருஷ்ணதேவராயர் தெலுங்கு மொழியில் இயற்றிய புகழ்பெற்ற இலக்கிய நூல் எது?","options":["மதுரா விஜயம்","பாரிஜாத அபகரணம்","மனுசரிதம்","ஆமுக்தமால்யதா"],"correctAnswer":3,"explanation":"'ஆந்திர போஜர்' எனப் போற்றப்பட்ட கிருஷ்ணதேவராயர் தெலுங்கு மொழியில் ஆண்டாள் வரலாற்றை அடிப்படையாகக் கொண்ட 'ஆமுக்தமால்யதா' என்ற காவியத்தையும், சமஸ்கிருத மொழியில் 'ஜாம்பவதி கல்யாணம்' என்ற நாடகத்தையும் எழுதினார். 'மதுரா விஜயம்' என்ற நூலை எழுதியவர் கங்காதேவி ஆவார்.","difficulty":"easy","topic":"விஜயநகரப் பேரரசு"},{"id":89,"subject":"gk","testNumber":1,"question":"கிருஷ்ணதேவராயரின் அரசவையை அலங்கரித்த 'அஷ்டதிக்கஜங்கள்' எனப்படும் எட்டு தெலுங்குக் கவிஞர்களில் முதன்மையானவராகவும் 'ஆந்திர கவிதா பிதாமகர்' எனவும் போற்றப்பட்டவர் யார்?","options":["தெனாலி ராமகிருஷ்ணர்","நந்தி திம்மண்ணா","அல்லசானி பெத்தண்ணா","பிங்கலி சூரண்ணா"],"correctAnswer":2,"explanation":"கிருஷ்ணதேவராயரின் அரசவையில் இருந்த எட்டு சிறந்த தெலுங்குப் புலவர்கள் 'அஷ்டதிக்கஜங்கள்' எனப்பட்டனர். அவர்களில் தலைசிறந்தவரான அல்லசானி பெத்தண்ணா 'மனுசரிதம்' என்ற நூலை எழுதினார்; இவர் 'ஆந்திர கவிதா பிதாமகர்' (தெலுங்குக் கவிதையின் தந்தை) எனப் போற்றப்படுகிறார்.","difficulty":"medium","topic":"விஜயநகரப் பேரரசு"},{"id":90,"subject":"gk","testNumber":1,"question":"கி.பி. 1565-ஆம் ஆண்டு நடைபெற்ற தலைக்கோட்டைப் போரில் (ராக்ஷச-தங்கடி போர்) தக்காண சுல்தானியக் கூட்டணியால் தோற்கடிக்கப்பட்டுக் கொல்லப்பட்ட விஜயநகரப் படைத்தளபதி யார்?","options":["திருமலைதேவராயர்","சதாசிவராயர்","அச்சுதராயர்","ராமராயர்"],"correctAnswer":3,"explanation":"1565 ஜனவரி 23-இல் பீஜப்பூர், அகமதுநகர், கோல்கொண்டா மற்றும் பீடார் ஆகிய நான்கு தக்காண சுல்தானியங்களின் கூட்டுப்படைகளுக்கும் விஜயநகரத்திற்கும் இடையே தலைக்கோட்டைப் போர் (ராக்ஷச-தங்கடி போர்) நடைபெற்றது. இதில் விஜயநகரப் படைக்குத் தலைமை தாங்கிய ராமராயர் தோற்கடிக்கப்பட்டுக் கொல்லப்பட்டார்; இதன் பின்னர் விஜயநகர நகரம் அழிக்கப்பட்டது.","difficulty":"medium","topic":"விஜயநகரப் பேரரசு"},{"id":91,"subject":"gk","testNumber":1,"question":"கி.பி. 1347-இல் தக்காணத்தில் பாமினி சுல்தானியத்தை நிறுவிய அலாவுதீன் ஹசன் பாமன் ஷாவின் இயற்பெயர் என்ன?","options":["மகமூத் கவான்","முகமது ஷா","பெரோஸ் ஷா பாமனி","ஹசன் கங்கு (ஜாபர் கான்)"],"correctAnswer":3,"explanation":"முகமது பின் துக்ளக்கின் ஆட்சிக்கு எதிராகத் தக்காணத்தில் கிளர்ச்சி செய்த ஹசன் கங்கு (ஜாபர் கான்), 1347-இல் 'அலாவுதீன் ஹசன் பாமன் ஷா' என்ற பெயருடன் பாமினி சுல்தானியத்தை நிறுவினார். இவர் குல்பர்காவைத் தனது தலைநகராகக் கொண்டார்; பின்னர் அகமது ஷா தலைநகரை பீடாருக்கு மாற்றினார்.","difficulty":"medium","topic":"பாமினி பேரரசு"},{"id":92,"subject":"gk","testNumber":1,"question":"பாமினி சுல்தான் மூன்றாம் முகமது ஷாவின் பிரதம அமைச்சராகப் பணியாற்றி, பீடாரில் 3,000 கையெழுத்துப் பிரதிகளைக் கொண்ட பிரம்மாண்ட மதரஸாவை (கல்வி நிலையம்) நிறுவியவர் யார்?","options":["குலி குதுப் ஷா","மாலிக் அகமது","யூசுப் ஆதில் ஷா","மகமூத் கவான்"],"correctAnswer":3,"explanation":"பாரசீக வணிகராக வந்து பாமினி அரசின் திறமையான பிரதம அமைச்சராக (வகீல்) உயர்ந்தவர் மகமூத் கவான் ஆவார். இவர் நிர்வாகச் சீர்திருத்தங்களை மேற்கொண்டதோடு, பீடாரில் புகழ்பெற்ற மதரஸா மற்றும் நூலகத்தை நிறுவினார்; போர்ச்சுகீசியர்களிடமிருந்து கோவாவைக் கைப்பற்றினார். 1481-இல் தக்காணப் பிரபுக்களின் சதியால் இவர் தூக்கிலிடப்பட்டார்.","difficulty":"medium","topic":"பாமினி பேரரசு"},{"id":93,"subject":"gk","testNumber":1,"question":"பீஜப்பூரில் அமைந்துள்ள உலகின் மிகப்பெரிய குவிமாடங்களில் ஒன்றும் 'விஸ்பரிங் கேலரி' (எதிரொலிக்கும் மாடம்) கொண்டதுமான 'கோல்கும்பாஸ்' யாரால் கட்டப்பட்டது?","options":["இப்ராஹிம் குதுப் ஷா","முகமது அடில் ஷா","யூசுப் அடில் ஷா","அலாவுதீன் பாமன் ஷா"],"correctAnswer":1,"explanation":"பாமினி அரசு ஐந்து தக்காண சுல்தானியங்களாகப் பிரிந்தபின், பீஜப்பூரை ஆட்சி செய்த அடில் ஷாஹி வம்ச அரசரான முகமது அடில் ஷாவின் கல்லறையாகக் 'கோல்கும்பாஸ்' கட்டப்பட்டது. இதன் குவிமாடம் எந்தத் தூண்களின் ஆதரவும் இன்றி அமைக்கப்பட்ட அற்புதமான தக்காணக் கட்டடக்கலைச் சின்னமாகும்.","difficulty":"hard","topic":"பாமினி பேரரசு"},{"id":94,"subject":"gk","testNumber":1,"question":"1674-ஆம் ஆண்டு ராய்கர் கோட்டையில் 'சத்ரபதி' என்ற பட்டத்துடன் முடிசூட்டிக் கொண்ட சிவாஜியின் எட்டு அமைச்சர்களைக் கொண்ட ஆலோசனைக் குழு எவ்வாறு அழைக்கப்பட்டது?","options":["நவரத்தினங்கள்","அஷ்டதிக்கஜங்கள்","அஷ்டபிரதான்","பஞ்சபிரதான்"],"correctAnswer":2,"explanation":"சத்ரபதி சிவாஜி தனது ஆட்சி நிர்வாகத்திற்கு உதவுவதற்காக எட்டு அமைச்சர்களைக் கொண்ட 'அஷ்டபிரதான்' என்ற குழுவை அமைத்தார். இதில் பிரதம அமைச்சர் 'பேஷ்வா' (முகிய பிரதான்), நிதி அமைச்சர் 'அமாத்யா' மற்றும் வெளியுறவு அமைச்சர் 'சுமந்த்' ஆகியோர் முக்கியப் பொறுப்புகளை வகித்தனர்.","difficulty":"easy","topic":"மராத்தியர்கள்"},{"id":95,"subject":"gk","testNumber":1,"question":"மராத்தியப் பேரரசின் ஆட்சியில் அண்டை பகுதிகளிலிருந்து சத்ரபதி சிவாஜி வசூலித்த 'சௌத்' மற்றும் 'சர்தேஷ்முகி' ஆகிய வரிகள் முறையே எவ்வளவு பங்கு ஆகும்?","options":["சௌத் - 1/10 (10%); சர்தேஷ்முகி - 1/4 (25%)","சௌத் - 1/3 (33%); சர்தேஷ்முகி - 1/6 (16.6%)","சௌத் - 1/5 (20%); சர்தேஷ்முகி - 1/8 (12.5%)","சௌத் - 1/4 (25%); சர்தேஷ்முகி - 1/10 (10%)"],"correctAnswer":3,"explanation":"மராத்தியர்களின் படையெடுப்பிலிருந்து பாதுகாப்புப் பெறுவதற்காக அண்டை அரசுகள் செலுத்திய வரி 'சௌத்' எனப்படும்; இது வருவாயில் நான்கில் ஒரு பங்கு (25%) ஆகும். சிவாஜி மராத்தியப் பகுதியின் பரம்பரைத் தலைவர் (சர்தேஷ்முக்) என்ற உரிமையில் வசூலித்த கூடுதல் வரி 'சர்தேஷ்முகி' ஆகும்; இது பத்தில் ஒரு பங்கு (10%) ஆகும்.","difficulty":"hard","topic":"மராத்தியர்கள்"},{"id":96,"subject":"gk","testNumber":1,"question":"கி.பி. 1665-இல் சத்ரபதி சிவாஜிக்கும் ஔரங்கசீப்பின் தளபதி ராஜா ஜெய்சிங்கிற்கும் இடையே கையெழுத்தான வரலாற்றுச் சிறப்புமிக்க உடன்படிக்கை எது?","options":["பஸ்சீன் உடன்படிக்கை","புரந்தர் உடன்படிக்கை","சால்பை உடன்படிக்கை","வட்கான் உடன்படிக்கை"],"correctAnswer":1,"explanation":"1665 ஜூன் மாதத்தில் சிவாஜிக்கும் முகலாயத் தளபதி அம்பர் நாட்டு ராஜா ஜெய்சிங்கிற்கும் இடையே 'புரந்தர் உடன்படிக்கை' கையெழுத்தானது. இதன்படி சிவாஜி தனது 35 கோட்டைகளில் 23 கோட்டைகளை முகலாயர்களிடம் ஒப்படைக்கவும், ஆக்ராவில் உள்ள ஔரங்கசீப்பின் அரசவைக்குச் செல்லவும் ஒப்புக்கொண்டார்.","difficulty":"medium","topic":"மராத்தியர்கள்"},{"id":97,"subject":"gk","testNumber":1,"question":"மராத்திய மன்னர் ஷாகுவால் 1713-இல் நியமிக்கப்பட்டு பேஷ்வா பதவியைப் பரம்பரைப் பதவியாக உயர்த்திய முதல் பேஷ்வா யார்?","options":["பாலாஜி விஸ்வநாத்","பாலாஜி பாஜிராவ்","முதலாம் பாஜிராவ்","மாதவராவ்"],"correctAnswer":0,"explanation":"சிவாஜியின் பேரனான ஷாகு 1713-இல் பாலாஜி விஸ்வநாத்தைத் தனது பேஷ்வாவாக (பிரதம அமைச்சர்) நியமித்தார். இவர் 1719-இல் முகலாயர்களிடம் தக்காணப் பகுதிகளுக்கான சௌத் மற்றும் சர்தேஷ்முகி வசூலிக்கும் உரிமையைப் பெற்று மராத்தியக் கூட்டமைப்பை வலுப்படுத்தினார்; இவருக்குப் பின் இவரது மகன் முதலாம் பாஜிராவ் பேஷ்வாவானார்.","difficulty":"medium","topic":"மராத்தியர்கள்"},{"id":98,"subject":"gk","testNumber":1,"question":"கி.பி. 1761 ஜனவரி 14-ஆம் நாள் நடைபெற்ற மூன்றாம் பானிபட் போரில் மராத்தியப் படைகளைத் தோற்கடித்த ஆப்கானியப் படையெடுப்பாளர் யார்?","options":["தைமூர்","நாதிர்ஷா","முகமது கோரி","அகமது ஷா அப்தாலி"],"correctAnswer":3,"explanation":"பேஷ்வா பாலாஜி பாஜிராவ் (நானா சாஹிப்) காலத்தில் 1761-இல் நடைபெற்ற மூன்றாம் பானிபட் போரில் ஆப்கானிய மன்னர் அகமது ஷா அப்தாலி, சதாசிவராவ் பாவ் மற்றும் விஸ்வாஸ் ராவ் தலைமையிலான மராத்தியப் படைகளைத் தோற்கடித்தார். இப்போர் இந்தியாவில் மராத்தியர்களின் மேலாதிக்கத்திற்குப் பெரும் பின்னடைவை ஏற்படுத்தியது.","difficulty":"easy","topic":"மராத்தியர்கள்"},{"id":99,"subject":"gk","testNumber":1,"question":"தென்னிந்திய பக்தி இயக்கத்தில் 'விசிஷ்டாத்வைதம்' என்ற தத்துவக் கோட்பாட்டைப் பரப்பிய வைணவத் துறவி யார்?","options":["ராமானுஜர்","மத்வாச்சாரியார்","ஆதிசங்கரர்","வல்லபாச்சாரியார்"],"correctAnswer":0,"explanation":"ஸ்ரீபெரும்புதூரில் பிறந்த வைணவப் பெரியாரான ராமானுஜர் 'விசிஷ்டாத்வைதம்' என்ற தத்துவத்தைப் போதித்தார்; இவர் அனைத்து சாதியினரும் கோயில்களில் வழிபடலாம் எனக் கூறினார். 'அத்வைதம்' ஆதிசங்கரராலும், 'துவைதம்' மத்வாச்சாரியாராலும் முன்வைக்கப்பட்ட தத்துவங்களாகும்.","difficulty":"medium","topic":"பக்தி & சூபி இயக்கம்"},{"id":100,"subject":"gk","testNumber":1,"question":"இந்தியாவில் 'சிஷ்டி' (Chishti) சூபி அமைப்பைப் பிரபலப்படுத்தியவரும், ராஜஸ்தானின் அஜ்மீரில் தர்கா கொண்டவருமான புகழ்பெற்ற சூபி துறவி யார்?","options":["பாபா பரீத்","நிஜாமுதீன் அவுலியா","குவாஜா மொய்னுதீன் சிஷ்டி","ஷேக் சலீம் சிஷ்டி"],"correctAnswer":2,"explanation":"12-ஆம் நூற்றாண்டில் இந்தியாவிற்கு வந்த குவாஜா மொய்னுதீன் சிஷ்டி, ராஜஸ்தானில் உள்ள அஜ்மீரைத் தனது மையமாகக் கொண்டு 'சிஷ்டி' சூபி மரபைப் பரப்பினார். அன்பு, சகோதரத்துவம் மற்றும் இசை (கவ்வாலி) மூலம் இறைவனை உணரலாம் எனப் போதித்த இவரது தர்கா அஜ்மீரில் உள்ளது.","difficulty":"medium","topic":"பக்தி & சூபி இயக்கம்"}]);
